@Composable
fun MandateSelectScreen(mainActions: MainActions) {
    val strings = LocalStrings.current.mandate

    Column(Modifier.fillMaxSize().background(paper)) {
        VortexTopBar(onBack = { mainActions.home() })
        KioskScrollColumn(
            modifier = Modifier
                .weight(1f)
                .fillMaxWidth(),
            contentPadding = PaddingValues(horizontal = 24.dp, vertical = 24.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
        ) {
            Column(Modifier.widthIn(max = 860.dp).fillMaxWidth()) {
                Text(
                    text = strings.selectTitle,
                    style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.Bold, fontSize = 32.sp, lineHeight = 38.sp),
                    color = ink,
                    modifier = Modifier.semantics { heading() },
                )
                Text(
                    text = strings.selectDescription,
                    style = TextStyle(fontFamily = BodyFamily(), fontSize = 17.sp),
                    color = ink2,
                    modifier = Modifier.padding(top = 6.dp),
                )
                Spacer(Modifier.height(20.dp))

                Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                    MandateRow(strings.selectLand) { mainActions.navigate(MainDestinations.LandMandate) }
                    MandateRow(strings.selectPeople) { mainActions.navigate(MainDestinations.PeopleMandate) }
                    MandateRow(strings.selectMilitary) { mainActions.navigate(MainDestinations.MilitaryMandate) }
                }
            }
        }
    }
}

@Composable
private fun MandateRow(title: String, onClick: () -> Unit) {
    RowCard(onClick = onClick) {
        Text(
            text = title,
            style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.SemiBold, fontSize = 18.sp, lineHeight = 22.sp),
            color = ink,
        )
    }
}
