package com.coding.va.selfhelp.presentation.screens.craft

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.coding.va.selfhelp.domain.model.CraftingResource
import com.coding.va.selfhelp.domain.model.EnergyType
import com.coding.va.selfhelp.domain.use_cases.AddCraftedItem
import com.coding.va.selfhelp.domain.use_cases.CanMakeCreation
import com.coding.va.selfhelp.domain.use_cases.GetActiveCharacterUseCase
import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.presentation.methods.ApiErrorDisplayProvider
import com.coding.va.selfhelp.presentation.screens.craft.model.CraftItemEvent
import com.coding.va.selfhelp.presentation.screens.craft.model.ItemCraftResourceForm
import com.coding.va.selfhelp.presentation.screens.craft.model.isValid
import com.coding.va.selfhelp.presentation.screens.craft.model.meetsMinRequirements
import com.coding.va.selfhelp.presentation.screens.craft.model.toResourcesText
import com.coding.va.selfhelp.presentation.screens.craft.model.toVerifySheet
import com.coding.va.selfhelp.presentation.screens.craft.model.toVortexCard
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.presentation.screens.mainscreen.destinations.MainDestinations
import com.coding.va.selfhelp.presentation.screens.success.model.SuccessData
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import org.koin.android.annotation.KoinViewModel

@KoinViewModel
class CraftItemViewModel(
    private val addCraftedItem: AddCraftedItem,
    private val canMakeCreation: CanMakeCreation,
    private val getActiveCharacter: GetActiveCharacterUseCase,
    private val strings: AppStrings,
) : ViewModel() {

    private val _display = MutableStateFlow(CraftItemDisplayProvider.provide(strings))
    val display = _display.asStateFlow()

    private var mainActions: MainActions? = null

    fun initVM(actions: MainActions, destination: MainDestinations.CraftItem = MainDestinations.CraftItem()) {
        mainActions = actions
        applyPrefill(destination)
        prefillActiveCharacter()
    }

    private fun prefillActiveCharacter() {
        val active = getActiveCharacter() ?: return
        val plin = Pair(active.plin.toString(), active.chin.toString())
        val currentForm = _display.value.form
        _display.value = _display.value.copy(
            form = currentForm.copy(
                resources = currentForm.resources.mapValues { (_, res) ->
                    if (res.plin.first.isBlank()) res.copy(plin = plin) else res
                }
            )
        )
    }

    private fun applyPrefill(dest: MainDestinations.CraftItem) {
        if (dest.prefillDescription.isBlank() && dest.prefillNotes.isBlank()
            && dest.prefillEnergy.isBlank() && dest.prefillResources.isBlank()) return

        val resources = mutableMapOf<Int, ItemCraftResourceForm>()
        if (dest.prefillResources.isNotBlank()) {
            dest.prefillResources.split(";").forEachIndexed { index, entry ->
                val parts = entry.split(",")
                if (parts.size >= 4) {
                    val resourceType = CraftingResource.entries.firstOrNull { it.name == parts[1] }
                    val energyType = EnergyType.entries.firstOrNull { it.name == parts[3] } ?: EnergyType.INSPIRATION
                    val plin = if (parts.size >= 6) Pair(parts[4], parts[5]) else Pair("", "")
                    resources[index + 1] = ItemCraftResourceForm(
                        resourceAmount = parts[0],
                        resourceType = resourceType,
                        energyAmount = parts[2],
                        energyType = energyType,
                        plin = plin,
                    )
                }
            }
        } else if (dest.prefillEnergy.isNotBlank()) {
            dest.prefillEnergy.split(",").forEachIndexed { index, entry ->
                val (typeName, amount) = entry.split(":")
                val energyType = EnergyType.entries.firstOrNull { it.name == typeName } ?: EnergyType.INSPIRATION
                resources[index + 1] = ItemCraftResourceForm(
                    energyAmount = amount,
                    energyType = energyType,
                )
            }
        }
        if (resources.isEmpty()) {
            resources[1] = ItemCraftResourceForm()
        }

        val updatedForm = _display.value.form.copy(
            description = dest.prefillDescription,
            imbueCap = dest.prefillImbueCap,
            notes = dest.prefillNotes,
            resources = resources,
        )
        _display.value = _display.value.copy(form = updatedForm)
    }

    fun onEvent(event: CraftItemEvent) {
        viewModelScope.launch {
            when (event) {
                is CraftItemEvent.AddResourceRow -> {
                    _display.emit(
                        _display.value.copy(
                            form = _display.value.form.copy(
                                resources = _display.value.form.resources.toMutableMap().apply {
                                    this[_display.value.form.resources.size + 1] =
                                        ItemCraftResourceForm(
                                            energyType = _display.value.form.resources[_display.value.form.resources.size]?.energyType
                                                ?: EnergyType.INSPIRATION,
                                            plin = _display.value.form.resources[_display.value.form.resources.size]?.plin
                                                ?: Pair("", ""),
                                        )
                                }
                            )
                        )
                    )
                }

                is CraftItemEvent.RemoveResourceRow -> {
                    _display.emit(
                        _display.value.copy(
                            form = _display.value.form.copy(
                                resources = _display.value.form.resources.toMutableMap()
                                    .apply { remove(event.row) }
                            )
                        )
                    )
                }

                is CraftItemEvent.UpdateCraftForm -> {
                    _display.emit(_display.value.copy(form = event.form))
                }

                is CraftItemEvent.DismissError -> {
                    _display.emit(
                        _display.value.copy(
                            shouldValidate = true,
                            errorBox = null,
                            verifySheet = null,
                        )
                    )
                }

                is CraftItemEvent.AddItem -> {
                    addItem()
                }

                is CraftItemEvent.Verify -> {
                    when {
                        _display.value.form.isValid() -> {
                            _display.emit(
                                _display.value.copy(
                                    shouldValidate = false,
                                    verifySheet = _display.value.form.toVerifySheet(false, canMakeCreation().getOrNull() ?: false, strings)
                                )
                            )
                        }

                        _display.value.form.meetsMinRequirements() -> {
                            _display.emit(
                                _display.value.copy(
                                    shouldValidate = true,
                                    verifySheet = _display.value.form.toVerifySheet(true, canMakeCreation().getOrNull() ?: false, strings)
                                )
                            )
                        }

                        else -> {
                            _display.emit(
                                _display.value.copy(
                                    shouldValidate = true,
                                    errorBox = CraftItemDisplayProvider.requiredError(strings)
                                )
                            )
                        }
                    }
                }

                is CraftItemEvent.Back -> {
                    mainActions?.home()
                }
            }
        }
    }

    private fun addItem() {
        viewModelScope.launch {
            _display.emit(
                _display.value.copy(
                    verifySheet = _display.value.verifySheet?.copy(
                        confirm = _display.value.verifySheet?.confirm?.copy(
                            loading = true
                        )!!
                    )
                )
            )
            addCraftedItem(_display.value.form)
                .onSuccess {
                    mainActions?.navigate(
                        MainDestinations.Success(
                            data = SuccessData(
                                cardDisplay = _display.value.form.toVortexCard(it.itemId),
                                entryData = it,
                                resourcesText = _display.value.form.toResourcesText(),
                                notes = _display.value.form.notes,
                            )
                        )
                    )
                }.onFailure {
                    _display.emit(
                        _display.value.copy(
                            shouldValidate = false,
                            verifySheet = null,
                            errorBox = ApiErrorDisplayProvider.error(it.message, strings)
                        )
                    )
                }
        }
    }
}
