@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun VerifySheet(
    display: VerifySheetDisplay,
    onDismiss: (() -> Unit)? = null,
    onConfirm: (() -> Unit)? = null
) {
    val sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true)
    val scope = rememberCoroutineScope()
    var showBottomSheet by remember { mutableStateOf(true) }

    ModalBottomSheet(
        modifier = Modifier.onlyDesktop { fillMaxWidth(0.5f) },
        containerColor = paperRaised,
        onDismissRequest = {
            showBottomSheet = false
            onDismiss?.invoke()
        },
        sheetState = sheetState,
    ) {
        VerifySheetContent(
            display = display,
            onDismiss = {
                scope.launch { sheetState.hide() }.invokeOnCompletion {
                    if (!sheetState.isVisible) {
                        showBottomSheet = false
                        onDismiss?.invoke()
                    }
                }
            },
            onConfirm = { onConfirm?.invoke() },
        )
    }
}

@OptIn(ExperimentalLayoutApi::class)
@Composable
fun VerifySheetContent(
    display: VerifySheetDisplay,
    onDismiss: (() -> Unit),
    onConfirm: (() -> Unit)
) {
    val a11y = LocalStrings.current.a11y
    val confirmFocusRequester = remember { FocusRequester() }
    LaunchedEffect(Unit) { confirmFocusRequester.requestFocus() }

    KioskScrollColumn(
        modifier = Modifier.fillMaxWidth()
            .onlyDesktop { fillMaxHeight(0.75f) }
            .onlyMobile { fillMaxHeight(0.90f) }
            .semantics { liveRegion = LiveRegionMode.Polite },
        contentPadding = PaddingValues(start = 24.dp, end = 24.dp, bottom = 32.dp),
    ) {
        Text(
            text = display.title,
            style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.Bold, fontSize = 26.sp),
            color = ink,
            modifier = Modifier.semantics { heading() },
        )
        Text(
            modifier = Modifier.padding(top = 6.dp),
            text = display.description,
            style = TextStyle(fontFamily = BodyFamily(), fontSize = 16.sp),
            color = ink2,
        )

        Spacer(Modifier.height(16.dp))
        CreationSummaryDetail(resources = display.resources, notes = display.notes)

        // sunken parchment well holding the front + back card preview
        Column(
            modifier = Modifier
                .padding(top = 20.dp)
                .fillMaxWidth()
                .clip(RoundedCornerShape(10.dp))
                .background(paperSunken)
                .border(1.dp, vellumLine, RoundedCornerShape(10.dp))
                .onlyDesktop { padding(28.dp) }
                .onlyMobile { padding(horizontal = 6.dp, vertical = 16.dp) },
            horizontalAlignment = Alignment.CenterHorizontally,
        ) {
            Text(
                text = display.lammyLabel,
                style = vortexMono().copy(fontSize = 12.sp, letterSpacing = 1.2.sp),
                color = ink3,
                textAlign = TextAlign.Center,
                modifier = Modifier.padding(bottom = 16.dp),
            )
            if (getPlatform() == TYPE.DESKTOP) {
                Row(modifier = Modifier.height(220.dp).fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(24.dp, Alignment.CenterHorizontally)) {
                    VortexItemCardUIFront(display = display.lammy, modifier = Modifier.fillMaxHeight())
                    VortexItemCardUIBack(display = display.lammy, modifier = Modifier.fillMaxHeight())
                }
            } else {
                FlowRow(horizontalArrangement = Arrangement.spacedBy(18.dp, Alignment.CenterHorizontally), verticalArrangement = Arrangement.spacedBy(18.dp)) {
                    VortexItemCardUIFront(display = display.lammy, modifier = Modifier.fillMaxWidth())
                    VortexItemCardUIBack(display = display.lammy, modifier = Modifier.fillMaxWidth())
                }
            }
        }

        Spacer(Modifier.height(24.dp))
        Row(verticalAlignment = Alignment.CenterVertically) {
            VortexButton(
                text = display.dismiss,
                onClick = { onDismiss() },
                variant = VortexButtonVariant.Ghost,
            )
            Spacer(Modifier.weight(1f))
            Box(
                modifier = Modifier
                    .focusRequester(confirmFocusRequester)
                    .semantics { if (display.confirm.loading) stateDescription = a11y.loading }
            ) {
                VortexButton(
                    text = display.confirm.label,
                    onClick = { onConfirm() },
                    enabled = !display.confirm.loading && display.confirm.enabled,
                )
            }
        }
    }
}
