package com.coding.va.selfhelp.data.models

import com.coding.va.selfhelp.domain.model.EntryType
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject

/**
 * Wire contract with the self-help backend. The app speaks in typed entry
 * payloads; the backend owns the mapping onto spreadsheet rows and columns.
 *
 * Keep in sync with the backend copy:
 * backend/src/main/kotlin/com/coding/va/selfhelp/backend/api/ApiModels.kt
 */
object BackendApiJson {
    val instance: Json = Json {
        ignoreUnknownKeys = true
        classDiscriminator = "kind"
        explicitNulls = false
    }
}

/** Returned by POST /entries/{type}: the appended row that anchors the entry. */
@Serializable
data class CreateEntryResponse(val row: Int)

/** Returned by GET /config: whether the self-help windows are currently open. */
@Serializable
data class ConfigResponse(
    val canMakeCreation: Boolean,
    val canSubmitMandate: Boolean,
)

/**
 * Body of PUT /entries/{type}/{row}. Discriminated by `kind`; the `card` and
 * `form` JSON blobs are app domain models the backend stores verbatim.
 */
@Serializable
sealed interface EntryPayload {
    val cardCode: String
    val platform: String
    val itemId: String
}

/** Craft / imbue / recharge / mundane entries — anything that prints a vortex card. */
@Serializable
@SerialName("card")
data class CardEntryPayload(
    override val cardCode: String,
    override val platform: String,
    override val itemId: String,
    /** The vortex card the print station renders. */
    val card: JsonObject,
    val itemName: String = "",
    val itemDescription: String = "",
    val imbue: String = "",
    val imbueCap: String = "",
    val resources: String = "",
    val notes: String = "",
) : EntryPayload

/** Land / people / military-order mandate forms. */
@Serializable
@SerialName("mandate")
data class MandateEntryPayload(
    override val cardCode: String,
    override val platform: String,
    override val itemId: String,
    /** The full mandate form. */
    val form: JsonObject,
    val formType: String,
    val ocName: String = "",
    val plin: String = "",
    val characterName: String = "",
    val subject: String = "",
    val formFields: String = "",
    val specialInstructions: String = "",
) : EntryPayload

/** Returned by GET /entries/{type}/{row} and PUT /entries/{type}/{row}. */
@Serializable
data class EntryResponse(
    val row: Int,
    val created: String,
    val cardCode: String,
    /** The vortex card or mandate form; null if the entry was never written. */
    val payload: JsonObject? = null,
    val platform: String,
    val printed: Boolean,
    /** Set for mandate entry types. */
    val formType: String? = null,
    val itemId: String,
)

/** An entry reference decoded from a scanned card code. */
data class EntryData(
    val rowNumber: String,
    val type: EntryType,
)
