package com.coding.va.selfhelp.presentation.components.plinfield.model

data class PlinFieldDisplay(
    val plinLabel: String,
    val plinHint: String,
    val chinLabel: String,
    val chinHint: String,
    val enabled: Boolean = true,
    val visible: Boolean = true,
)

fun Pair<String, String>.plinToText() = "${this.first}|${this.second}"

