package com.coding.va.selfhelp.presentation.commoninterface

import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.lifecycle.Lifecycle
import androidx.lifecycle.LifecycleOwner
import androidx.lifecycle.repeatOnLifecycle
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.collect

@Composable
fun LifecycleOwner.onCreate(
    key: Any? = Unit,
    block: suspend CoroutineScope.() -> Unit,
) {
    LaunchedEffect(key ?: Unit) { repeatOnLifecycle(Lifecycle.State.CREATED, block) }
}

/**
 * Runs [block] each time this owner re-enters the RESUMED state, i.e. every time
 * the screen returns to the foreground (including back-navigation from another
 * destination). Use for state that can change while the screen sits paused in the
 * back stack, such as login status after logging out elsewhere.
 */
@Composable
fun LifecycleOwner.onResume(
    key: Any? = Unit,
    block: suspend CoroutineScope.() -> Unit,
) {
    LaunchedEffect(key ?: Unit) { repeatOnLifecycle(Lifecycle.State.RESUMED, block) }
}

suspend fun <T> Flow<T?>.collectNonNull(block: (T) -> Unit) {
    collect {
        it?.let(block::invoke)
    }
}

fun String.toIntOrZero() = this.toIntOrNull() ?: 0

fun Float.ceil(): Int = kotlin.math.ceil(this).toInt()

fun Float?.orZero() = this ?: 0f

fun Int?.orZero() = this ?: 0