@Composable
fun LoginContent(
    display: LoginScreenDisplay,
    onEvent: ((LoginScreenEvent) -> Unit)? = null,
) {
    val a11y = LocalStrings.current.a11y

    Column(Modifier.fillMaxSize().background(paper)) {
        VortexTopBar(onBack = { onEvent?.invoke(LoginScreenEvent.Back) })

        when (display) {
            is LoginScreenDisplay.Loading -> {
                Box(
                    modifier = Modifier.fillMaxSize().semantics { liveRegion = LiveRegionMode.Polite; contentDescription = a11y.loading },
                    contentAlignment = Alignment.Center,
                ) { CircularProgressIndicator() }
            }

            is LoginScreenDisplay.Display -> {
                LoginScroll {
                    Image(
                        painter = painterResource(Res.drawable.vortex_logo),
                        contentDescription = null,
                        modifier = Modifier.size(88.dp),
                    )
                    Text(
                        text = display.title,
                        style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.Bold, fontSize = 32.sp),
                        color = ink,
                        textAlign = TextAlign.Center,
                        modifier = Modifier.padding(top = 16.dp).semantics { heading() },
                    )
                    Spacer(Modifier.height(16.dp))

                    if (display.isAuthenticating) {
                        Box(
                            modifier = Modifier.fillMaxWidth().padding(vertical = 24.dp).semantics {
                                liveRegion = LiveRegionMode.Polite
                                contentDescription = a11y.loading
                            },
                            contentAlignment = Alignment.Center,
                        ) {
                            Column(horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(12.dp)) {
                                CircularProgressIndicator()
                                Text(
                                    text = display.statusLabel,
                                    style = TextStyle(fontFamily = BodyFamily(), fontSize = 16.sp),
                                    color = ink2,
                                    textAlign = TextAlign.Center,
                                )
                            }
                        }
                    } else {
                        Text(
                            text = display.statusLabel,
                            style = TextStyle(fontFamily = BodyFamily(), fontSize = 16.sp),
                            color = ink2,
                            textAlign = TextAlign.Center,
                        )
                        VortexButton(
                            text = LocalStrings.current.login.signInButton,
                            onClick = { onEvent?.invoke(LoginScreenEvent.RetrySignIn) },
                            modifier = Modifier.fillMaxWidth().padding(top = 8.dp),
                        )
                    }
                }
            }

            is LoginScreenDisplay.Error -> {
                LoginScroll {
                    Text(
                        text = display.title,
                        style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.Bold, fontSize = 32.sp),
                        color = ink,
                        textAlign = TextAlign.Center,
                        modifier = Modifier.semantics { heading() },
                    )
                    Text(
                        text = display.description,
                        style = TextStyle(fontFamily = BodyFamily(), fontSize = 16.sp),
                        color = crest,
                        modifier = Modifier.padding(top = 12.dp).fillMaxWidth().clip(RoundedCornerShape(5.dp)).background(crimsonTint).padding(16.dp),
                    )
                    Spacer(Modifier.height(16.dp))
                    VortexButton(text = display.retryButton, onClick = { onEvent?.invoke(LoginScreenEvent.RetrySignIn) }, modifier = Modifier.fillMaxWidth())
                }
            }

            is LoginScreenDisplay.LoggedIn -> {
                LoginScroll {
                    Text(
                        text = display.title,
                        style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.Bold, fontSize = 32.sp),
                        color = ink,
                        textAlign = TextAlign.Center,
                        modifier = Modifier.semantics { heading() },
                    )
                    Text(
                        text = display.label,
                        style = TextStyle(fontFamily = BodyFamily(), fontSize = 16.sp),
                        color = ink2,
                        modifier = Modifier.padding(top = 12.dp).fillMaxWidth().clip(RoundedCornerShape(5.dp)).background(successTint).padding(16.dp),
                    )
                }
            }
        }
    }
}

@Composable
private fun LoginScroll(content: @Composable androidx.compose.foundation.layout.ColumnScope.() -> Unit) {
    KioskScrollColumn(
        modifier = Modifier.fillMaxWidth(),
        contentPadding = PaddingValues(horizontal = 24.dp, vertical = 32.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Column(
            modifier = Modifier.widthIn(max = 380.dp).fillMaxWidth(),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(12.dp),
            content = content,
        )
    }
}