package com.coding.va.selfhelp.presentation.screens.mandate.people

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.coding.va.selfhelp.data.mapper.subject
import com.coding.va.selfhelp.domain.model.MandateForm
import com.coding.va.selfhelp.domain.use_cases.CanSubmitMandate
import com.coding.va.selfhelp.domain.use_cases.GetActiveCharacterUseCase
import com.coding.va.selfhelp.domain.use_cases.GetCharacterDetailUseCase
import com.coding.va.selfhelp.domain.use_cases.SavedCreationUseCase
import com.coding.va.selfhelp.domain.use_cases.SubmitMandateForm
import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.presentation.screens.mainscreen.destinations.MainDestinations
import com.coding.va.selfhelp.presentation.screens.mandate.common.isValid
import com.coding.va.selfhelp.presentation.screens.mandate.common.toSavedCreation
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import org.koin.android.annotation.KoinViewModel

@KoinViewModel
class PeopleMandateViewModel(
    private val submitMandate: SubmitMandateForm,
    private val canSubmitMandate: CanSubmitMandate,
    private val getActiveCharacter: GetActiveCharacterUseCase,
    private val getCharacterDetail: GetCharacterDetailUseCase,
    private val savedCreationUseCase: SavedCreationUseCase,
    private val strings: AppStrings,
) : ViewModel() {

    private val _form = MutableStateFlow(MandateForm.People())
    val form = _form.asStateFlow()

    private val _submitting = MutableStateFlow(false)
    val submitting = _submitting.asStateFlow()

    private val _error = MutableStateFlow<String?>(null)
    val error = _error.asStateFlow()

    private val _locked = MutableStateFlow(false)
    val locked = _locked.asStateFlow()

    private val _shouldValidate = MutableStateFlow(false)
    val shouldValidate = _shouldValidate.asStateFlow()

    private var mainActions: MainActions? = null

    fun initVM(actions: MainActions) {
        mainActions = actions
        prefillActiveCharacter()
    }

    private fun prefillActiveCharacter() {
        val active = getActiveCharacter() ?: return
        if (_form.value.plin.first.isBlank() && _form.value.plin.second.isBlank()) {
            _form.value = _form.value.copy(
                plin = Pair(active.plin.toString(), active.chin.toString())
            )
        }
        viewModelScope.launch {
            getCharacterDetail(active.plin, active.chin)
                .onSuccess { detail ->
                    if (_form.value.characterName.isBlank()) {
                        _form.value = _form.value.copy(characterName = detail.name)
                    }
                }
        }
    }

    fun update(form: MandateForm.People) {
        _form.value = form
    }

    fun submit() {
        if (_submitting.value) return
        val current = _form.value
        if (!current.isValid()) {
            _shouldValidate.value = true
            return
        }
        _shouldValidate.value = false
        _submitting.value = true
        _error.value = null
        _locked.value = false
        viewModelScope.launch {
            val allowed = canSubmitMandate().getOrNull() ?: false
            if (!allowed) {
                _submitting.value = false
                _locked.value = true
                return@launch
            }
            submitMandate(current)
                .onSuccess { entry ->
                    _submitting.value = false
                    savedCreationUseCase.set(current.toSavedCreation(entry, strings))
                        .onFailure { println("Error saving mandate to history: $it") }
                    mainActions?.navigate(
                        MainDestinations.MandateSubmitted(
                            formTypeLabel = strings.entryTypes.peopleMandate,
                            subject = current.subject(),
                            cardCode = entry.getCardCode,
                        )
                    )
                }
                .onFailure {
                    _submitting.value = false
                    _error.value = it.message ?: strings.common.apiErrorTitle
                }
        }
    }

    fun dismissError() {
        _error.value = null
        _locked.value = false
    }

    fun back() {
        mainActions?.back()
    }
}
