package com.coding.va.selfhelp.presentation.screens.login

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import co.touchlab.kermit.Logger
import com.coding.va.selfhelp.auth.OAUTH_CALLBACK_SCHEME
import com.coding.va.selfhelp.auth.OAUTH_CALLBACK_URI
import com.coding.va.selfhelp.auth.OAuthBridge
import com.coding.va.selfhelp.auth.buildKeycloakAuthUrl
import com.coding.va.selfhelp.auth.generatePkce
import com.coding.va.selfhelp.di.ERU_KEYCLOAK_CLIENT_ID
import com.coding.va.selfhelp.di.currentEruEnvironment
import com.coding.va.selfhelp.di.launchOAuthBrowser
import com.coding.va.selfhelp.domain.exceptions.AccountNotLinkedException
import com.coding.va.selfhelp.domain.use_cases.ExchangeEruCodeUseCase
import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.presentation.screens.login.model.LoginScreenDisplay
import com.coding.va.selfhelp.presentation.screens.login.model.LoginScreenEvent
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.presentation.screens.mainscreen.destinations.MainDestinations
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import kotlin.random.Random
import org.koin.android.annotation.KoinViewModel

private val log = Logger.withTag("LoginFlow")

@KoinViewModel
class LoginViewModel(
    private val exchangeEruCode: ExchangeEruCodeUseCase,
    private val strings: AppStrings,
) : ViewModel() {

    private val _display = MutableStateFlow<LoginScreenDisplay>(LoginDisplayProvider.authenticating(strings))
    val display = _display.asStateFlow()

    private var mainActions: MainActions? = null

    // OAuth state tracking — set before opening the browser, cleared after callback.
    private var pendingOAuthState: String? = null
    private var pendingCodeVerifier: String? = null

    fun initVM(actions: MainActions) {
        mainActions = actions
        viewModelScope.launch { listenForOAuthCallback() }
        viewModelScope.launch { listenForOAuthCancellation() }
        viewModelScope.launch { startKeycloakLogin() }
    }

    private suspend fun startKeycloakLogin() {
        log.d { "Login - starting hosted Keycloak login flow" }
        _display.emit(LoginDisplayProvider.authenticating(strings))

        val state = Random.nextBytes(16).joinToString("") { byte ->
            val hex = (byte.toInt() and 0xFF).toString(16)
            if (hex.length == 1) "0$hex" else hex
        }
        val (codeVerifier, codeChallenge) = generatePkce()

        pendingOAuthState = state
        pendingCodeVerifier = codeVerifier

        val authUri = buildKeycloakAuthUrl(
            issuer = currentEruEnvironment.baseUrl,
            clientId = ERU_KEYCLOAK_CLIENT_ID,
            redirectUri = OAUTH_CALLBACK_URI,
            state = state,
            codeChallenge = codeChallenge,
            socialOnly = true,
        )

        log.d { "Login - launching Keycloak auth URL" }
        launchOAuthBrowser(authUri, OAUTH_CALLBACK_SCHEME)
    }

    private suspend fun listenForOAuthCallback() {
        log.d { "Login - OAuthBridge callback listener started" }
        OAuthBridge.callbacks.collect { callback ->
            log.d { "Login - OAuthBridge callback received: code=${callback.code.take(8)}… state=${callback.state}" }

            val state = pendingOAuthState ?: run {
                log.w { "Login - No pending OAuth state — ignoring callback" }
                return@collect
            }

            if (callback.state != state) {
                log.e { "Login - State mismatch! expected=$state received=${callback.state}" }
                pendingOAuthState = null
                pendingCodeVerifier = null
                _display.emit(LoginDisplayProvider.error(strings))
                return@collect
            }

            log.d { "Login - State verified — exchanging code with Keycloak" }
            pendingOAuthState = null
            val codeVerifier = pendingCodeVerifier
            pendingCodeVerifier = null

            _display.emit(LoginDisplayProvider.authenticating(strings))

            exchangeEruCode(callback.code, OAUTH_CALLBACK_URI, codeVerifier)
                .onSuccess {
                    log.d { "Login - Keycloak code exchange OK — navigating to CharacterSelect" }
                    mainActions?.navigate(MainDestinations.CharacterSelect)
                }
                .onFailure { err ->
                    log.e(err) { "Login - Token exchange failed: ${err.message}" }
                    if (err is AccountNotLinkedException) {
                        _display.emit(LoginDisplayProvider.unlinkedAccount(strings))
                    } else {
                        _display.emit(LoginDisplayProvider.error(strings))
                    }
                }
        }
    }

    private suspend fun listenForOAuthCancellation() {
        OAuthBridge.cancellations.collect {
            log.d { "Login - OAuth flow cancelled by user" }
            pendingOAuthState = null
            pendingCodeVerifier = null
            _display.emit(LoginDisplayProvider.cancelled(strings))
        }
    }

    fun onEvent(event: LoginScreenEvent) {
        viewModelScope.launch {
            when (event) {
                is LoginScreenEvent.RetrySignIn -> startKeycloakLogin()
                is LoginScreenEvent.Back -> mainActions?.back()
            }
        }
    }
}