data class CraftItemDisplay(
    val title: String,
    val description: String,
    val resourceDescription: String,
    val currentlyFromResourcesLabel: String,
    val backButton: String,
    val nextButton: String,
    val itemTitle: FieldDisplay,
    val itemDescription: FieldDisplay,
    val itemNotes: FieldDisplay,
    val itemImbueCap: FieldDisplay,
    val itemCraftResource: ItemCraftResourceDisplay,
    val form: ItemCraftForm,
    val shouldValidate: Boolean,
    val errorBox: ErrorBoxDisplay?,
    val verifySheet: VerifySheetDisplay?,
)

data class ItemCraftResourceDisplay(
    val resourceAmount: FieldDisplay,
    val resourceType: SelectableFieldDisplay,
    val energyAmount: FieldDisplay,
    val energyType: SelectableFieldDisplay,
    val plin: PlinFieldDisplay,
)

typealias ItemCraftForm = com.coding.va.selfhelp.domain.model.ItemCraftForm
typealias ItemCraftResourceForm = com.coding.va.selfhelp.domain.model.ItemCraftResourceForm

/** Raw (un-rounded) energy this row costs, before any per-crafter rounding. */
private fun ItemCraftResourceForm.rawEnergy(): Float {
    val required = resourceType?.requiredEnergy.orZero()
    // Resources with a fixed per-unit cost are derived; OTHER/manual rows
    // (cost 0) keep the value the crafter typed into the energy field.
    return if (required > 0f) required * resourceAmount.toIntOrZero()
    else energyAmount.toIntOrZero().toFloat()
}

/**
 * Energy charged per energy type, rounded once per crafter.
 *
 * Fractional material costs (e.g. 0.5 Inspiration) are summed per crafter
 * before rounding up, so a single crafter making two 0.5-cost materials pays 1
 * (not 2). Different crafters still round independently, so one 0.5 material
 * each still costs them 1 apiece.
 */
fun ItemCraftForm.energyUsedByType(): Map<EnergyType, Int> =
    resources.values
        .groupBy { it.energyType }
        .mapValues { (_, rows) ->
            rows.groupBy { it.plin }
                .values
                .sumOf { crafterRows -> crafterRows.fold(0f) { acc, r -> acc + r.rawEnergy() }.ceil() }
        }

fun ItemCraftForm.toVortexCard(tempItin: String): VortexItemCardDisplay {
    return VortexItemCardDisplay(
        itemName = name,
        itemDescription = description,
        energyUsed = energyUsedByType(),
        craftResources = resources.values.map { r ->
            CraftResourceEntry(
                resourceAmount = r.resourceAmount,
                resourceType = r.resourceType?.name.orEmpty(),
                energyAmount = r.energyAmount,
                energyType = r.energyType.name,
                plin = r.plin.first,
                chin = r.plin.second,
            )
        },
        imbueCap = imbueCap,
        createdBy = resources.map { it.value.plin.plinToText() }.distinctBy { it }.joinToString("+"),
        tempItin = tempItin,
        power = null,
        header = EnStrings.craft.vortexCardHeader,
        event = currentEventName(),
    )
}

fun ItemCraftForm.getResourcesImbueCap(): Int =
    this.resources.map { it.value.resourceAmount.toIntOrZero() * it.value.resourceType?.imbueCap.orZero() }
        .sum()

fun ItemCraftForm.isTitleValid(): Boolean = name.isNotBlank()
fun ItemCraftForm.isDescriptionValid(): Boolean = description.isNotBlank()
fun ItemCraftForm.isImbueCapValid(): Boolean =
    imbueCap.toIntOrZero() > 0 && imbueCap.toIntOrZero() == getResourcesImbueCap()

fun ItemCraftResourceForm.isResourceAmountValid(): Boolean =
    resourceAmount.isNotBlank() && resourceAmount.toIntOrZero() > 0

fun ItemCraftResourceForm.isEnergyAmountValid(): Boolean =
    energyAmount.toIntOrZero() == (resourceAmount.toIntOrZero() * resourceType?.requiredEnergy.orZero()).ceil()
        .toInt()

fun ItemCraftResourceForm.isPlinValid(): Boolean = plin.first.isNotBlank() && plin.second.isNotBlank()
fun ItemCraftResourceForm.isResourceTypeValid(): Boolean = resourceType != null
fun ItemCraftResourceForm.isEnergyTypeValid(): Boolean = energyType != null

fun ItemCraftResourceForm.isValid(): Boolean {
    return isResourceAmountValid() && isEnergyAmountValid() && isPlinValid() && isResourceTypeValid() && isEnergyTypeValid()
}

fun Map<Int, ItemCraftResourceForm>.meetsMinRequirements(): Boolean {
    return this.values.any { it.isPlinValid() && it.isResourceTypeValid() && it.isResourceAmountValid() }
}

fun ItemCraftForm.isValid(): Boolean {
    return isTitleValid() && isDescriptionValid() && isImbueCapValid() && resources.all { it.value.isValid() }
}

fun ItemCraftForm.meetsMinRequirements(): Boolean {
    return isTitleValid() && isDescriptionValid() && resources.meetsMinRequirements()
}

fun ItemCraftForm.toResourcesText(): String {
    return resources.map {
        EnStrings.craft.craftResourceEntry
            .replace(AMOUNT, it.value.resourceAmount)
            .replace(RESOURCE, it.value.resourceType?.resourceName.orEmpty())
            .replace(ENERGY_AMOUNT, it.value.energyAmount)
            .replace(ENERGY_TYPE, it.value.energyType.localizedName(EnStrings))
            .replace(PLIN, it.value.plin.plinToText()) +
            if (!it.value.isEnergyAmountValid()) EnStrings.craft.energyAmountModified else ""
    }.joinToString(separator = "\n") + if (!isImbueCapValid()) {
        "\n\n" + EnStrings.craft.imbueCapIssue
            .replace(IMBUECAP, this.imbueCap.toString())
            .replace(RESOURCECAP, this.getResourcesImbueCap().toString())
    } else ""
}

fun ItemCraftForm.toVerifySheet(hasErrors: Boolean, isEnabled: Boolean, strings: AppStrings): VerifySheetDisplay {
    return VerifySheetDisplay(
        title = if (hasErrors) strings.verify.titleHasErrors else strings.verify.titleNoErrors,
        description = if (hasErrors) strings.verify.descriptionHasErrorsCreation else strings.verify.descriptionNoErrors,
        dismiss = strings.verify.dismiss,
        confirm = LoadingButtonDisplay(strings.verify.confirm, false, isEnabled),
        resources = this.toResourcesText(),
        notes = notes,
        lammyLabel = strings.verify.craftLammyLabel,
        lammy = this.toVortexCard("---")
    )
}

