package com.coding.va.selfhelp.utils

const val BASE_URL = "https://sheets.googleapis.com"
const val DB_NAME = "example.db"

enum class TYPE(val displayName: String) {
    ANDROID("android"),
    IOS("iOS"),
    DESKTOP("desktop"),
    WEB("web");

    /** True for touch-based platforms (Android and iOS). */
    val isMobile: Boolean get() = this == ANDROID || this == IOS || this == WEB

    /** True only for platforms that support the va-selfhelp:// OAuth callback flow. */
    val supportsOAuthLogin: Boolean get() = this == ANDROID || this == IOS
}

enum class Screens {
    MAIN,
    DETAIL
}