@Composable
fun RechargeContent(
    display: RechargeDisplay,
    onEvent: ((RechargeEvent) -> Unit)? = null
) {
    val numberRegex = remember { Regex("^\\d+\$") }
    val strings = LocalStrings.current
    val numericKeyboard = KeyboardOptions(keyboardType = KeyboardType.Number)
    val helpStyle = TextStyle(fontFamily = BodyFamily(), fontSize = 14.sp, color = ink3)

    fun update(form: com.coding.va.selfhelp.domain.model.RechargeForm) =
        onEvent?.invoke(RechargeEvent.UpdateRechargeForm(form))

    display.errorBox?.let {
        ErrorBox(display = it, onConfirmation = { }, onDismissRequest = { onEvent?.invoke(RechargeEvent.DismissError) })
    }
    display.verifySheet?.let {
        VerifySheet(
            display = it,
            onConfirm = { onEvent?.invoke(RechargeEvent.AddRecharge) },
            onDismiss = { onEvent?.invoke(RechargeEvent.DismissError) },
        )
    }

    FormShell(
        title = display.title,
        desc = display.description,
        onBack = { onEvent?.invoke(RechargeEvent.Back) },
        cancelLabel = display.backButton,
        nextLabel = display.nextButton,
        onCancel = { onEvent?.invoke(RechargeEvent.Back) },
        onNext = { onEvent?.invoke(RechargeEvent.Verify) },
    ) {
        // ---- Item ----
        FormSection(title = strings.common.sectionItem) {
            val invalid = display.shouldValidate && !display.form.isTargetValid()
            VortexField(
                label = display.rechargeTarget.label,
                value = display.form.targetItin.orEmpty(),
                hint = display.rechargeTarget.hint,
                error = if (invalid) strings.a11y.errorRequired else null,
                mono = true,
                onValueChange = { update(display.form.copy(targetItin = it)) },
            )
        }

        // ---- Energy (one block per recharge resource) ----
        display.form.rechargeResources.forEach { entry ->
            FormSection(title = strings.common.sectionEnergy) {
                VortexField(
                    fieldWidth = 160.dp,
                    label = display.rechargeResource.energyAmount.label,
                    value = entry.value.energyAmount,
                    hint = display.rechargeResource.energyAmount.hint,
                    error = if (display.shouldValidate && !entry.value.isEnergyAmountValid()) strings.a11y.errorNumbersOnly else null,
                    mono = true,
                    keyboardOptions = numericKeyboard,
                    numericOnly = true,
                    placeholder = "0",
                    onValueChange = {
                        update(
                            display.form.copy(
                                rechargeResources = display.form.rechargeResources.toMutableMap().apply {
                                    this[entry.key] = entry.value.copy(energyAmount = it)
                                }
                            )
                        )
                    },
                )
                Spacer(Modifier.height(16.dp))
                PlinTextField(
                    display = display.rechargeResource.plin,
                    label = strings.recharge.rechargerPlinLabel,
                    value = entry.value.headRechargerPlin,
                    isError = display.shouldValidate && !entry.value.isPlinValid(),
                    errorText = if (display.shouldValidate && !entry.value.isPlinValid()) strings.a11y.errorInvalidPlin else null,
                    onValueChange = {
                        update(
                            display.form.copy(
                                rechargeResources = display.form.rechargeResources.toMutableMap().apply {
                                    this[entry.key] = entry.value.copy(
                                        headRechargerPlin = it,
                                        energySuppliers = entry.value.energySuppliers.toMutableMap().apply {
                                            this[1] = this[1]?.copy(plin = it) ?: RechargeEnergySupplier()
                                        },
                                    )
                                }
                            )
                        )
                    },
                )
                Spacer(Modifier.height(16.dp))
                Ledger {
                    LedgerLine(
                        label = display.rechargeResource.currentEnergyLabel.trim(),
                        amount = entry.value.energySuppliers.values.mapNotNull { it.amount.toIntOrNull() }.sum().toString(),
                    )
                }
                Spacer(Modifier.height(16.dp))
                SelectableField(
                    label = strings.common.selectEnergyTypeLabel,
                    display = display.rechargeResource.energyType,
                    value = entry.value.energyType.localizedName(strings),
                    onSelected = {
                        update(
                            display.form.copy(
                                rechargeResources = display.form.rechargeResources.toMutableMap().apply {
                                    this[entry.key] = entry.value.copy(energyType = EnergyType.valueOf(it.id))
                                }
                            )
                        )
                    },
                )

                // suppliers
                Spacer(Modifier.height(16.dp))
                Text(
                    text = display.rechargeResource.energySupplierDescription.replace(ENERGY_TYPE, entry.value.energyType.localizedName(strings)),
                    style = helpStyle,
                )
                Spacer(Modifier.height(12.dp))
                Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                    SupplierHeader(plinLabel = strings.common.supplierPlinLabel, amountLabel = strings.common.amountLabel)
                    entry.value.energySuppliers.forEach { supplier ->
                        Row(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalAlignment = Alignment.Top) {
                            PlinTextField(
                                display = display.rechargeResource.energySupplierPlin,
                            expandHelper = false,
                                value = supplier.value.plin,
                                onValueChange = {
                                    update(
                                        display.form.copy(
                                            rechargeResources = display.form.rechargeResources.toMutableMap().apply {
                                                this[entry.key] = entry.value.copy(
                                                    energySuppliers = entry.value.energySuppliers.toMutableMap().apply {
                                                        this[supplier.key] = supplier.value.copy(plin = it)
                                                    }
                                                )
                                            }
                                        )
                                    )
                                },
                            )
                            VortexField(
                                fieldWidth = 90.dp, expandHelper = false,
                                value = supplier.value.amount,
                                error = if (display.shouldValidate && !entry.value.isEnergyAmountValid()) strings.a11y.errorNumbersOnly else null,
                                mono = true,
                                enabled = display.rechargeResource.energySupplierAmount.enabled,
                                keyboardOptions = numericKeyboard,
                                numericOnly = true,
                                placeholder = "0",
                                onValueChange = {
                                    update(
                                        display.form.copy(
                                            rechargeResources = display.form.rechargeResources.toMutableMap().apply {
                                                this[entry.key] = entry.value.copy(
                                                    energySuppliers = entry.value.energySuppliers.toMutableMap().apply {
                                                        this[supplier.key] = supplier.value.copy(amount = it)
                                                    }
                                                )
                                            }
                                        )
                                    )
                                },
                            )
                            if (entry.value.energySuppliers.size > 1) {
                                VortexIconButton(
                                    symbol = "−",
                                    contentDescription = strings.a11y.removeRow,
                                    onClick = { onEvent?.invoke(RechargeEvent.RemovePowerSupplier(entry.key, supplier.key)) },
                                )
                            }
                        }
                    }
                    VortexButton(
                        text = "＋ " + strings.common.addSupplierLabel,
                        onClick = { onEvent?.invoke(RechargeEvent.AddPowerSupplier(entry.key)) },
                        variant = VortexButtonVariant.Secondary,
                    )
                }
            }
        }

        // ---- Special Notes ----
        FormSection(title = strings.common.specialNotesLabel) {
            VortexField(
                value = display.form.notes,
                hint = display.rechargeNotes.hint,
                singleLine = false,
                minHeight = 96.dp,
                onValueChange = { update(display.form.copy(notes = it)) },
            )
        }

        Spacer(Modifier.height(8.dp))
    }
}
