package com.coding.va.selfhelp.presentation.screens.mandate.people

import androidx.compose.foundation.layout.Spacer
import androidx.compose.foundation.layout.height
import androidx.compose.runtime.Composable
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import androidx.lifecycle.compose.LocalLifecycleOwner
import com.coding.va.selfhelp.domain.model.MandateHelpHinderOther
import com.coding.va.selfhelp.domain.model.MandateYesNo
import com.coding.va.selfhelp.domain.model.MandateYesNoOther
import com.coding.va.selfhelp.i18n.LocalStrings
import com.coding.va.selfhelp.presentation.commoninterface.onCreate
import com.coding.va.selfhelp.presentation.components.FormSection
import com.coding.va.selfhelp.presentation.components.FormShell
import com.coding.va.selfhelp.presentation.components.VortexField
import com.coding.va.selfhelp.presentation.components.errorbox.ErrorBox
import com.coding.va.selfhelp.presentation.components.errorbox.model.ErrorBoxDisplay
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.presentation.screens.mandate.common.MandateBaseFields
import com.coding.va.selfhelp.presentation.screens.mandate.common.MandateRadioRow

@Composable
fun PeopleMandateScreen(
    viewModel: PeopleMandateViewModel,
    mainActions: MainActions,
) {
    val form by viewModel.form.collectAsState()
    val submitting by viewModel.submitting.collectAsState()
    val error by viewModel.error.collectAsState()
    val locked by viewModel.locked.collectAsState()
    val shouldValidate by viewModel.shouldValidate.collectAsState()

    LocalLifecycleOwner.current.onCreate(form) { viewModel.initVM(mainActions) }

    val strings = LocalStrings.current
    val mStrings = strings.mandate

    val yesNoOptions = listOf(MandateYesNo.YES to mStrings.choiceYes, MandateYesNo.NO to mStrings.choiceNo)
    val yesNoOtherOptions = listOf(
        MandateYesNoOther.YES to mStrings.choiceYes,
        MandateYesNoOther.NO to mStrings.choiceNo,
        MandateYesNoOther.OTHER to mStrings.choiceOther,
    )
    val helpHinderOptions = listOf(
        MandateHelpHinderOther.HELP to mStrings.choiceHelp,
        MandateHelpHinderOther.HINDER to mStrings.choiceHinder,
        MandateHelpHinderOther.OTHER to mStrings.choiceOther,
    )

    val errorBox: ErrorBoxDisplay? = when {
        locked -> ErrorBoxDisplay(mStrings.lockedTitle, mStrings.lockedDescription, null, strings.common.apiErrorButton)
        error != null -> ErrorBoxDisplay(strings.common.apiErrorTitle, strings.common.apiErrorDescriptionPrefix + error, null, strings.common.apiErrorButton)
        else -> null
    }
    errorBox?.let {
        ErrorBox(display = it, onConfirmation = { viewModel.dismissError() }, onDismissRequest = { viewModel.dismissError() })
    }

    FormShell(
        title = mStrings.peopleTitle,
        desc = mStrings.peopleDescription,
        onBack = { viewModel.back() },
        cancelLabel = mStrings.backButton,
        nextLabel = mStrings.submitButton,
        onCancel = { viewModel.back() },
        onNext = { viewModel.submit() },
        nextEnabled = !submitting,
    ) {
        FormSection(title = strings.common.sectionYourDetails) {
            MandateBaseFields(
                strings = mStrings,
                ocName = form.ocName,
                plin = form.plin,
                characterName = form.characterName,
                onOcNameChange = { viewModel.update(form.copy(ocName = it)) },
                onPlinChange = { viewModel.update(form.copy(plin = it)) },
                onCharacterNameChange = { viewModel.update(form.copy(characterName = it)) },
                shouldValidate = shouldValidate,
            )
            Spacer(Modifier.height(16.dp))
            val peopleNameError = shouldValidate && form.peopleName.isBlank()
            VortexField(
                label = mStrings.peopleNameLabel,
                value = form.peopleName,
                onValueChange = { viewModel.update(form.copy(peopleName = it)) },
                error = if (peopleNameError) strings.a11y.errorRequired else null,
            )
        }

        FormSection(title = mStrings.peopleMigrateLabel) {
            MandateRadioRow(options = yesNoOptions, selected = form.migrate, onSelect = { viewModel.update(form.copy(migrate = it)) })
            if (form.migrate == MandateYesNo.YES) {
                Spacer(Modifier.height(16.dp))
                VortexField(
                    label = mStrings.peopleMigrateWhereLabel,
                    value = form.migrateWhere,
                    onValueChange = { viewModel.update(form.copy(migrateWhere = it)) },
                )
            }
        }

        FormSection(title = mStrings.peopleMilitiaLabel) {
            MandateRadioRow(options = yesNoOtherOptions, selected = form.militia, onSelect = { viewModel.update(form.copy(militia = it)) })
            if (form.militia == MandateYesNoOther.OTHER) {
                Spacer(Modifier.height(16.dp))
                VortexField(
                    label = mStrings.peopleMilitiaOtherLabel,
                    value = form.militiaOther,
                    singleLine = false,
                    minHeight = 96.dp,
                    onValueChange = { viewModel.update(form.copy(militiaOther = it)) },
                )
            }
        }

        FormSection(title = mStrings.peopleGrowLabel) {
            MandateRadioRow(options = yesNoOtherOptions, selected = form.grow, onSelect = { viewModel.update(form.copy(grow = it)) })
            if (form.grow == MandateYesNoOther.OTHER) {
                Spacer(Modifier.height(16.dp))
                VortexField(
                    label = mStrings.peopleGrowOtherLabel,
                    value = form.growOther,
                    singleLine = false,
                    minHeight = 96.dp,
                    onValueChange = { viewModel.update(form.copy(growOther = it)) },
                )
            }
        }

        FormSection(title = mStrings.peopleOccupationLabel) {
            MandateRadioRow(options = helpHinderOptions, selected = form.occupationStance, onSelect = { viewModel.update(form.copy(occupationStance = it)) })
            if (form.occupationStance == MandateHelpHinderOther.OTHER) {
                Spacer(Modifier.height(16.dp))
                VortexField(
                    label = mStrings.peopleOccupationOtherLabel,
                    value = form.occupationOther,
                    singleLine = false,
                    minHeight = 96.dp,
                    onValueChange = { viewModel.update(form.copy(occupationOther = it)) },
                )
            }
        }

        FormSection {
            VortexField(
                label = mStrings.peopleOtherAdviceLabel,
                value = form.otherAdvice,
                singleLine = false,
                minHeight = 120.dp,
                onValueChange = { viewModel.update(form.copy(otherAdvice = it)) },
            )
        }

        Spacer(Modifier.height(8.dp))
    }
}
