/**
 * Composite identity field — six digits in two joined parts (PLIN ≤4, CHIN ≤2), per the design's
 * `.plin-row`. A single contextual [label] sits above; the two boxes carry short "PLIN"/"CHIN"
 * placeholders. Numeric only; the first box auto-advances to the second.
 */
@Composable
fun PlinTextField(
    display: PlinFieldDisplay,
    value: Pair<String, String> = Pair("", ""),
    isError: Boolean = false,
    errorText: String? = null,
    onValueChange: (Pair<String, String>) -> Unit = {},
    modifier: Modifier = Modifier,
    label: String? = null,
    expandHelper: Boolean = true,
    plinWidth: Dp = 64.dp,
) {
    val numberRegex = remember { Regex("^\\d+\$") }
    val strings = LocalStrings.current
    val a11y = strings.a11y
    val common = strings.common
    val plinFocusRequester = remember { FocusRequester() }
    val chinFocusRequester = remember { FocusRequester() }
    // The boxes always carry the short "PLIN"/"CHIN" placeholders. A contextual label (e.g.
    // "Receiver PLIN") supplied either via [label] or via a non-generic display.plinLabel sits above.
    val resolvedLabel = label ?: display.plinLabel.takeIf { it != common.plinLabel }

    Column(modifier) {
        if (resolvedLabel != null) {
            Text(
                text = resolvedLabel,
                style = TextStyle(fontFamily = BodyFamily(), fontSize = 14.sp, fontWeight = FontWeight.SemiBold, color = ink2),
                modifier = Modifier.padding(bottom = 8.dp),
            )
        }
        Row(
            verticalAlignment = Alignment.Top,
            modifier = Modifier.semantics { contentDescription = a11y.plinCompositeLabel },
        ) {
            PlinBox(
                value = value.first,
                width = plinWidth,
                isError = isError,
                enabled = display.enabled,
                leftRounded = true,
                imeAction = ImeAction.Next,
                modifier = Modifier.focusRequester(plinFocusRequester),
                onValueChange = {
                    if (it.isEmpty() || (it.matches(numberRegex) && it.length <= 4)) {
                        onValueChange(value.copy(first = it))
                        if (it.length == 4) chinFocusRequester.requestFocus()
                    }
                },
            )
            PlinBox(
                value = value.second,
                width = 46.dp,
                isError = isError,
                enabled = display.enabled,
                leftRounded = false,
                imeAction = ImeAction.Done,
                modifier = Modifier.focusRequester(chinFocusRequester).offset(x = (-1.5f).dp),
                onValueChange = {
                    if (it.isEmpty() || (it.matches(numberRegex) && it.length <= 2)) {
                        onValueChange(value.copy(second = it))
                    }
                    if (it.isEmpty()) plinFocusRequester.requestFocus()
                },
            )
        }
        FieldFooter(
            error = if (isError) errorText else null,
            hint = display.plinHint.takeIf { it.isNotBlank() },
            expand = expandHelper,
            constrainWidth = plinWidth + 46.dp,
        )
    }
}

@Composable
private fun PlinBox(
    value: String,
    width: Dp,
    isError: Boolean,
    enabled: Boolean,
    leftRounded: Boolean,
    imeAction: ImeAction,
    onValueChange: (String) -> Unit,
    modifier: Modifier = Modifier,
) {
    val interaction = remember { MutableInteractionSource() }
    val focused by interaction.collectIsFocusedAsState()
    val radius = VortexRadius.md
    val shape = if (leftRounded) {
        RoundedCornerShape(topStart = radius, bottomStart = radius)
    } else {
        RoundedCornerShape(topEnd = radius, bottomEnd = radius)
    }
    val borderColor = when {
        isError -> errorInk
        focused -> crest
        else -> inkFaint
    }
    val textStyle = vortexMono().copy(fontSize = 17.sp, color = ink)
    Box(
        modifier = modifier
            .width(width)
            .heightIn(min = 48.dp)
            .clip(shape)
            .background(paperRaised)
            .border(1.5.dp, borderColor, shape)
            .padding(horizontal = 10.dp, vertical = 12.dp)
            .moveFocusOnTab(),
        contentAlignment = Alignment.CenterStart,
    ) {
        BasicTextField(
            value = value,
            onValueChange = onValueChange,
            enabled = enabled,
            singleLine = true,
            textStyle = textStyle,
            cursorBrush = SolidColor(crest),
            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.NumberPassword, imeAction = imeAction),
            interactionSource = interaction,
        )
    }
}
