package com.coding.va.selfhelp.i18n

/** Typed placeholder constants for template strings. toString() returns the bracket key. */
sealed class StringPlaceholder(val key: String) {
    override fun toString(): String = key

    object AMOUNT : StringPlaceholder("[AMOUNT]")
    object RESOURCE : StringPlaceholder("[RESOURCE]")
    object ENERGY_AMOUNT : StringPlaceholder("[ENERGY_AMOUNT]")
    object ENERGY_TYPE : StringPlaceholder("[ENERGY_TYPE]")
    object PLIN : StringPlaceholder("[PLIN]")
    object IMBUECAP : StringPlaceholder("[IMBUECAP]")
    object RESOURCECAP : StringPlaceholder("[RESOURCECAP]")
    object IMBUE_TYPE : StringPlaceholder("[IMBUE_TYPE]")
    object IMBUE_OPTION : StringPlaceholder("[IMBUE_OPTION]")
    object SKILL_SPELL : StringPlaceholder("[SKILL_SPELL]")
    object SKILL : StringPlaceholder("[SKILL]")
    object QTY : StringPlaceholder("[QTY]")
    object VALUE : StringPlaceholder("[VALUE]")
}

/** Replace a typed placeholder in this template string with the given value. */
fun String.replace(placeholder: StringPlaceholder, value: String): String =
    replace(placeholder.key, value)
