package com.coding.va.selfhelp.presentation.screens.recharge

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.coding.va.selfhelp.domain.model.EnergyType
import com.coding.va.selfhelp.domain.use_cases.AddRecharge
import com.coding.va.selfhelp.domain.use_cases.CanMakeCreation
import com.coding.va.selfhelp.domain.use_cases.GetActiveCharacterUseCase
import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.presentation.methods.ApiErrorDisplayProvider
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.presentation.screens.mainscreen.destinations.MainDestinations
import com.coding.va.selfhelp.presentation.screens.recharge.model.RechargeEnergySupplier
import com.coding.va.selfhelp.presentation.screens.recharge.model.RechargeEvent
import com.coding.va.selfhelp.presentation.screens.recharge.model.RechargeResourceForm
import com.coding.va.selfhelp.presentation.screens.recharge.model.isValid
import com.coding.va.selfhelp.presentation.screens.recharge.model.meetsMinRequirements
import com.coding.va.selfhelp.presentation.screens.recharge.model.toResourcesText
import com.coding.va.selfhelp.presentation.screens.recharge.model.toVerifySheet
import com.coding.va.selfhelp.presentation.screens.recharge.model.toVortexCard
import com.coding.va.selfhelp.presentation.screens.success.model.SuccessData
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import org.koin.android.annotation.KoinViewModel

@KoinViewModel
class RechargeViewModel(
    private val addRechargeToSheet: AddRecharge,
    private val canMakeCreation: CanMakeCreation,
    private val getActiveCharacter: GetActiveCharacterUseCase,
    private val strings: AppStrings,
) : ViewModel() {

    private val _display = MutableStateFlow(RechargeDisplayProvider.provide(strings))
    val display = _display.asStateFlow()

    private var mainActions: MainActions? = null

    fun initVM(actions: MainActions, destination: MainDestinations.RechargeItem = MainDestinations.RechargeItem()) {
        mainActions = actions
        applyPrefill(destination)
        prefillActiveCharacter()
    }

    private fun prefillActiveCharacter() {
        val active = getActiveCharacter() ?: return
        val plin = Pair(active.plin.toString(), active.chin.toString())
        val currentForm = _display.value.form
        _display.value = _display.value.copy(
            form = currentForm.copy(
                rechargeResources = currentForm.rechargeResources.mapValues { (_, res) ->
                    res.copy(
                        headRechargerPlin = if (res.headRechargerPlin.first.isBlank()) plin else res.headRechargerPlin,
                        energySuppliers = res.energySuppliers.mapValues { (_, supplier) ->
                            if (supplier.plin.first.isBlank()) supplier.copy(plin = plin) else supplier
                        }
                    )
                }
            )
        )
    }

    private fun applyPrefill(dest: MainDestinations.RechargeItem) {
        if (dest.prefillItin.isBlank()) return
        val energyType = EnergyType.entries.firstOrNull { it.name == dest.prefillEnergyType }
            ?: EnergyType.SPIRITUAL_MANA
        val currentForm = _display.value.form
        val updatedResource = (currentForm.rechargeResources[1] ?: RechargeResourceForm()).copy(
            energyAmount = dest.prefillEnergyAmount,
            energyType = energyType,
            headRechargerPlin = Pair(dest.prefillPlin, dest.prefillChin),
        )
        val updatedForm = currentForm.copy(
            targetItin = dest.prefillItin,
            rechargeResources = currentForm.rechargeResources.toMutableMap().apply {
                this[1] = updatedResource
            }
        )
        _display.value = _display.value.copy(form = updatedForm)
    }

    fun onEvent(event: RechargeEvent) {
        viewModelScope.launch {
            when (event) {
                is RechargeEvent.AddPowerSupplier -> {
                    _display.emit(
                        _display.value.copy(
                            form = _display.value.form.copy(
                                rechargeResources = _display.value.form.rechargeResources.toMutableMap()
                                    .apply {
                                        val size = this[event.resource]?.energySuppliers?.size ?: 1
                                        this[event.resource] = this[event.resource]?.copy(
                                            energySuppliers = (this[event.resource]?.energySuppliers?.toMutableMap() ?: mutableMapOf())
                                                .apply {
                                                    this[size + 1] = RechargeEnergySupplier()
                                                }
                                        ) ?: RechargeResourceForm()
                                    }
                            )
                        )
                    )
                }

                is RechargeEvent.RemovePowerSupplier -> {
                    _display.emit(
                        _display.value.copy(
                            form = _display.value.form.copy(
                                rechargeResources = _display.value.form.rechargeResources.toMutableMap()
                                    .apply {
                                        this[event.resource] = this[event.resource]?.copy(
                                            energySuppliers = (this[event.resource]?.energySuppliers?.toMutableMap() ?: mutableMapOf())
                                                .apply { remove(event.row) }
                                        ) ?: RechargeResourceForm()
                                    }
                            )
                        )
                    )
                }

                is RechargeEvent.UpdateRechargeForm -> {
                    _display.emit(_display.value.copy(form = event.form))
                }

                is RechargeEvent.Back -> {
                    mainActions?.home()
                }

                is RechargeEvent.Verify -> {
                    when {
                        _display.value.form.isValid() -> {
                            _display.emit(
                                _display.value.copy(
                                    shouldValidate = false,
                                    verifySheet = _display.value.form.toVerifySheet(false, canMakeCreation().getOrNull() ?: false, strings)
                                )
                            )
                        }

                        _display.value.form.meetsMinRequirements() -> {
                            _display.emit(
                                _display.value.copy(
                                    shouldValidate = true,
                                    verifySheet = _display.value.form.toVerifySheet(true, canMakeCreation().getOrNull() ?: false, strings)
                                )
                            )
                        }

                        else -> {
                            _display.emit(
                                _display.value.copy(
                                    shouldValidate = true,
                                    errorBox = RechargeDisplayProvider.requiredError(strings)
                                )
                            )
                        }
                    }
                }

                is RechargeEvent.AddRecharge -> {
                    addRecharge()
                }

                is RechargeEvent.DismissError -> {
                    _display.emit(
                        _display.value.copy(
                            shouldValidate = true,
                            errorBox = null,
                            verifySheet = null,
                        )
                    )
                }
            }
        }
    }

    private fun addRecharge() {
        viewModelScope.launch {
            _display.emit(
                _display.value.copy(
                    verifySheet = _display.value.verifySheet?.copy(
                        confirm = _display.value.verifySheet?.confirm?.copy(
                            loading = true
                        )!!
                    )
                )
            )
            addRechargeToSheet(_display.value.form)
                .onSuccess {
                    mainActions?.navigate(
                        MainDestinations.Success(
                            data = SuccessData(
                                cardDisplay = _display.value.form.toVortexCard(it.itemId),
                                entryData = it,
                                resourcesText = _display.value.form.toResourcesText(),
                                notes = _display.value.form.notes,
                            )
                        )
                    )
                }.onFailure {
                    _display.emit(
                        _display.value.copy(
                            shouldValidate = false,
                            verifySheet = null,
                            errorBox = ApiErrorDisplayProvider.error(it.message, strings)
                        )
                    )
                }
        }
    }
}
