package com.coding.va.selfhelp.presentation.screens.character.select

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import co.touchlab.kermit.Logger
import com.coding.va.selfhelp.domain.model.CharacterSummary
import com.coding.va.selfhelp.domain.use_cases.GetCharactersUseCase
import com.coding.va.selfhelp.domain.use_cases.SaveActiveCharacterUseCase
import com.coding.va.selfhelp.domain.respository.AuthRepository
import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.presentation.screens.character.select.model.CharacterSelectEvent
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.presentation.screens.mainscreen.destinations.MainDestinations
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import org.koin.android.annotation.KoinViewModel

private val log = Logger.withTag("CharacterSelect")

@KoinViewModel
class CharacterSelectViewModel(
    private val getCharacters: GetCharactersUseCase,
    private val saveActiveCharacter: SaveActiveCharacterUseCase,
    private val authRepository: AuthRepository,
    private val strings: AppStrings,
) : ViewModel() {

    private val _display = MutableStateFlow(
        CharacterSelectDisplayProvider.loading()
    )
    val display = _display.asStateFlow()

    private var mainActions: MainActions? = null

    fun initVM(actions: MainActions) {
        mainActions = actions
        viewModelScope.launch { loadCharacters() }
    }

    private suspend fun loadCharacters() {
        _display.emit(CharacterSelectDisplayProvider.loading())

        val plin = authRepository.getPlin().getOrNull()
        if (plin == null) {
            log.w { "CharacterSelect - Could not resolve plin from Eru profile" }
            _display.emit(CharacterSelectDisplayProvider.error(strings))
            return
        }

        log.d { "CharacterSelect - loading characters for plin=$plin" }
        getCharacters(plin)
            .onSuccess { loaded ->
                log.d { "CharacterSelect - loaded ${loaded.size} characters" }
                _display.emit(CharacterSelectDisplayProvider.display(strings, loaded))
            }
            .onFailure { err ->
                log.e(err) { "CharacterSelect - failed: ${err.message}" }
                _display.emit(CharacterSelectDisplayProvider.error(strings))
            }
    }

    fun onEvent(event: CharacterSelectEvent) {
        viewModelScope.launch {
            when (event) {
                is CharacterSelectEvent.SelectCharacter -> {
                    log.d { "CharacterSelect - selected plin=${event.plin} chin=${event.chin}" }
                    saveActiveCharacter(event.plin, event.chin)
                    mainActions?.navigate(MainDestinations.Landing)
                }

                is CharacterSelectEvent.Retry -> loadCharacters()

                is CharacterSelectEvent.Back -> mainActions?.back()
            }
        }
    }
}