package com.coding.va.selfhelp.presentation.screens.landing

import androidx.compose.runtime.Composable
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.lifecycle.compose.LocalLifecycleOwner
import com.coding.va.selfhelp.presentation.commoninterface.collectNonNull
import com.coding.va.selfhelp.presentation.commoninterface.onCreate
import com.coding.va.selfhelp.presentation.commoninterface.onResume
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions

@Composable
fun LandingScreen(
    viewModel: LandingViewModel,
    mainActions: MainActions
) {
    val display by viewModel.display.collectAsState()

    LocalLifecycleOwner.current.onCreate(mainActions) {
        viewModel.navigate.collectNonNull(mainActions::navigate)
    }

    // Login state can change while Landing sits in the back stack (e.g. logging out
    // on the character screen). Recompute the login button each time we return here.
    LocalLifecycleOwner.current.onResume {
        viewModel.refresh()
    }

    LandingContent(display, viewModel::onEvent)
}