package com.coding.va.selfhelp.presentation.screens.model

import kotlinx.datetime.Month
import kotlinx.datetime.TimeZone
import kotlinx.datetime.toLocalDateTime
import kotlin.time.Clock
import kotlin.time.ExperimentalTime

/**
 * Returns the name of the current Vortex event based on the current month:
 *  - April / May / June  -> "Moots 1 {year}"
 *  - July / August       -> "Summoning {year}"
 *  - October             -> "Moots 2 {year}"
 *  - All other months    -> "Special? {year}"
 */
@OptIn(ExperimentalTime::class)
fun currentEventName(): String {
    val now = Clock.System.now().toLocalDateTime(TimeZone.currentSystemDefault())
    val year = now.year
    return when (now.month) {
        Month.APRIL, Month.MAY, Month.JUNE -> "Moots 1 $year"
        Month.JULY, Month.AUGUST           -> "Summoning $year"
        Month.OCTOBER                      -> "Moots 2 $year"
        else                               -> "Special? $year"
    }
}
