package com.coding.va.selfhelp.presentation.screens.mundane.model

sealed class MundaneEvent {
    data class UpdateForm(val form: MundaneForm) : MundaneEvent()
    /** Add a new inspiration supplier row */
    data class AddInspirationSupplier(val afterKey: Int) : MundaneEvent()
    /** Remove an inspiration supplier row by its key */
    data class RemoveInspirationSupplier(val key: Int) : MundaneEvent()
    data object Verify : MundaneEvent()
    data object Confirm : MundaneEvent()
    data object DismissError : MundaneEvent()
    data object Back : MundaneEvent()
}
