package com.coding.va.selfhelp.presentation.screens.craft

import com.coding.va.selfhelp.domain.model.CraftingResource
import com.coding.va.selfhelp.domain.model.EnergyType
import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.i18n.localizedName
import com.coding.va.selfhelp.presentation.components.errorbox.model.ErrorBoxDisplay
import com.coding.va.selfhelp.presentation.components.plinfield.model.PlinFieldDisplay
import com.coding.va.selfhelp.presentation.components.selectablefield.model.SelectableFieldContent
import com.coding.va.selfhelp.presentation.components.selectablefield.model.SelectableFieldDisplay
import com.coding.va.selfhelp.presentation.screens.craft.model.CraftItemDisplay
import com.coding.va.selfhelp.presentation.screens.craft.model.ItemCraftForm
import com.coding.va.selfhelp.presentation.screens.craft.model.ItemCraftResourceDisplay
import com.coding.va.selfhelp.presentation.screens.craft.model.ItemCraftResourceForm
import com.coding.va.selfhelp.presentation.screens.model.FieldDisplay

object CraftItemDisplayProvider {

    fun provide(strings: AppStrings) = CraftItemDisplay(
        title = strings.craft.title,
        description = strings.craft.description,
        resourceDescription = strings.craft.resourceDescription,
        currentlyFromResourcesLabel = strings.craft.currentlyFromResourcesLabel,
        backButton = strings.common.backToHome,
        nextButton = strings.craft.nextButton,
        itemTitle = FieldDisplay(
            label = strings.craft.itemTitleLabel,
            hint = strings.craft.itemTitleHint,
        ),
        itemDescription = FieldDisplay(
            label = strings.craft.itemDescriptionLabel,
            hint = strings.craft.itemDescriptionHint,
        ),
        itemNotes = FieldDisplay(
            label = strings.common.specialNotesLabel,
            hint = strings.common.specialNotesHint,
        ),
        itemImbueCap = FieldDisplay(
            label = strings.craft.itemImbueCapLabel,
            hint = strings.craft.itemImbueCapHint,
        ),
        itemCraftResource = provideEmptyCraftResource(strings),
        form = ItemCraftForm(
            name = "",
            description = "",
            imbueCap = "",
            notes = "",
            resources = mutableMapOf(1 to ItemCraftResourceForm())
        ),
        shouldValidate = false,
        errorBox = null,
        verifySheet = null,
    )

    fun provideEmptyCraftResource(strings: AppStrings) = ItemCraftResourceDisplay(
        resourceAmount = FieldDisplay(
            label = strings.common.amountLabel,
            hint = strings.craft.resourceAmountHint,
        ),
        resourceType = SelectableFieldDisplay(
            label = strings.craft.selectResourceLabel,
            content = CraftingResource.entries.map {
                SelectableFieldContent(
                    it.resourceName,
                    it.name
                )
            }
        ),
        energyAmount = FieldDisplay(
            label = strings.common.energyLabel,
            hint = strings.common.energyHint,
        ),
        energyType = SelectableFieldDisplay(
            label = strings.common.selectEnergyTypeLabel,
            content = EnergyType.entries.map {
                SelectableFieldContent(
                    it.localizedName(strings),
                    it.name
                )
            }
        ),
        plin = PlinFieldDisplay(
            plinLabel = strings.common.plinLabel,
            plinHint = strings.craft.crafterPlinHint,
            chinLabel = strings.common.chinLabel,
            chinHint = strings.common.chinLabel,
        ),
    )

    fun requiredError(strings: AppStrings) = ErrorBoxDisplay(
        title = strings.common.requiredErrorTitle,
        description = strings.common.requiredErrorDescription,
        acceptButton = null,
        retryButton = strings.common.requiredErrorButton,
    )
}
