package com.coding.va.selfhelp.domain.auth

import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi
import kotlin.time.Clock
import kotlin.time.ExperimentalTime

/**
 * Reads the `exp` (expiry) claim from a JWT *without* verifying its signature —
 * enough to decide whether a stored access token is still worth treating as a
 * live session when gating UI. Real requests remain validated server-side.
 *
 * @return the expiry as epoch seconds, or null when the token isn't a JWT we can
 * read, so callers can fall back to a presence-only check for opaque tokens.
 */
@OptIn(ExperimentalEncodingApi::class)
fun jwtExpiryEpochSeconds(token: String): Long? {
    val parts = token.split('.')
    if (parts.size < 2) return null
    val payload = parts[1]
    val padded = payload + "=".repeat((4 - payload.length % 4) % 4)
    val json = try {
        Base64.UrlSafe.decode(padded).decodeToString()
    } catch (e: Exception) {
        return null
    }
    return Regex("\"exp\"\\s*:\\s*(\\d+)").find(json)?.groupValues?.get(1)?.toLongOrNull()
}

/**
 * True when [token] is a JWT whose `exp` has already passed (minus [leewaySeconds]).
 * Unreadable / opaque tokens are treated as not expired so they keep working.
 */
@OptIn(ExperimentalTime::class)
fun isAccessTokenExpired(token: String, leewaySeconds: Long = 0): Boolean {
    val exp = jwtExpiryEpochSeconds(token) ?: return false
    return Clock.System.now().epochSeconds >= exp - leewaySeconds
}
