package com.coding.va.selfhelp.presentation.screens.mandate.land

import androidx.compose.foundation.layout.Spacer
import androidx.compose.foundation.layout.height
import androidx.compose.foundation.layout.width
import androidx.compose.foundation.text.KeyboardOptions
import androidx.compose.runtime.Composable
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.input.KeyboardType
import androidx.compose.ui.unit.dp
import androidx.lifecycle.compose.LocalLifecycleOwner
import com.coding.va.selfhelp.i18n.LocalStrings
import com.coding.va.selfhelp.presentation.commoninterface.onCreate
import com.coding.va.selfhelp.presentation.components.FormSection
import com.coding.va.selfhelp.presentation.components.FormShell
import com.coding.va.selfhelp.presentation.components.VortexField
import com.coding.va.selfhelp.presentation.components.errorbox.ErrorBox
import com.coding.va.selfhelp.presentation.components.errorbox.model.ErrorBoxDisplay
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.presentation.screens.mandate.common.MandateBaseFields

@Composable
fun LandMandateScreen(
    viewModel: LandMandateViewModel,
    mainActions: MainActions,
) {
    val form by viewModel.form.collectAsState()
    val submitting by viewModel.submitting.collectAsState()
    val error by viewModel.error.collectAsState()
    val locked by viewModel.locked.collectAsState()
    val shouldValidate by viewModel.shouldValidate.collectAsState()

    LocalLifecycleOwner.current.onCreate(form) { viewModel.initVM(mainActions) }

    val strings = LocalStrings.current
    val numberRegex = remember { Regex("^\\d{0,3}$") }
    val numericKeyboard = KeyboardOptions(keyboardType = KeyboardType.Number)

    val errorBox: ErrorBoxDisplay? = when {
        locked -> ErrorBoxDisplay(strings.mandate.lockedTitle, strings.mandate.lockedDescription, null, strings.common.apiErrorButton)
        error != null -> ErrorBoxDisplay(strings.common.apiErrorTitle, strings.common.apiErrorDescriptionPrefix + error, null, strings.common.apiErrorButton)
        else -> null
    }
    errorBox?.let {
        ErrorBox(display = it, onConfirmation = { viewModel.dismissError() }, onDismissRequest = { viewModel.dismissError() })
    }

    FormShell(
        title = strings.mandate.landTitle,
        desc = strings.mandate.landDescription,
        onBack = { viewModel.back() },
        cancelLabel = strings.mandate.backButton,
        nextLabel = strings.mandate.submitButton,
        onCancel = { viewModel.back() },
        onNext = { viewModel.submit() },
        nextEnabled = !submitting,
    ) {
        FormSection(title = strings.common.sectionYourDetails) {
            MandateBaseFields(
                strings = strings.mandate,
                ocName = form.ocName,
                plin = form.plin,
                characterName = form.characterName,
                onOcNameChange = { viewModel.update(form.copy(ocName = it)) },
                onPlinChange = { viewModel.update(form.copy(plin = it)) },
                onCharacterNameChange = { viewModel.update(form.copy(characterName = it)) },
                shouldValidate = shouldValidate,
            )
        }

        FormSection {
            val landNameError = shouldValidate && form.landName.isBlank()
            VortexField(
                label = strings.mandate.landNameLabel,
                value = form.landName,
                onValueChange = { viewModel.update(form.copy(landName = it)) },
                error = if (landNameError) strings.a11y.errorRequired else null,
            )
            Spacer(Modifier.height(16.dp))
            VortexField(
                fieldWidth = 220.dp,
                label = strings.mandate.landTaxationLabel,
                value = form.taxationPer100,
                hint = strings.mandate.landTaxationHint,
                mono = true,
                keyboardOptions = numericKeyboard,
                                numericOnly = true,
                                placeholder = "0",
                onValueChange = { if (it.isEmpty() || it.matches(numberRegex)) viewModel.update(form.copy(taxationPer100 = it)) },
            )
            Spacer(Modifier.height(16.dp))
            VortexField(
                label = strings.mandate.landSpendFirstLabel,
                value = form.spendFirstOn,
                hint = strings.mandate.landSpendFirstHint,
                singleLine = false,
                minHeight = 96.dp,
                onValueChange = { viewModel.update(form.copy(spendFirstOn = it)) },
            )
            Spacer(Modifier.height(16.dp))
            VortexField(
                label = strings.mandate.landSpendLeftoverLabel,
                value = form.spendLeftoverOn,
                singleLine = false,
                minHeight = 96.dp,
                onValueChange = { viewModel.update(form.copy(spendLeftoverOn = it)) },
            )
            Spacer(Modifier.height(16.dp))
            VortexField(
                label = strings.mandate.landDisbandLabel,
                value = form.disband,
                singleLine = false,
                minHeight = 96.dp,
                onValueChange = { viewModel.update(form.copy(disband = it)) },
            )
        }

        FormSection {
            VortexField(
                label = strings.mandate.landSpecialInstructionsLabel,
                value = form.specialInstructions,
                singleLine = false,
                minHeight = 120.dp,
                onValueChange = { viewModel.update(form.copy(specialInstructions = it)) },
            )
        }

        Spacer(Modifier.height(8.dp))
    }
}
