package com.coding.va.selfhelp.data.respository

import com.coding.va.selfhelp.data.network.EruAuthApi
import com.coding.va.selfhelp.domain.constants.Constants.SETTINGS_KEY_ACCESS_TOKEN
import com.coding.va.selfhelp.domain.constants.Constants.SETTINGS_KEY_REFRESH_TOKEN
import com.coding.va.selfhelp.domain.respository.AuthRepository
import com.russhwolf.settings.Settings
import org.koin.core.annotation.Single

@Single
class AuthRepositoryImp(
    private val api: EruAuthApi,
) : AuthRepository {

    private val settings = Settings()

    override suspend fun exchangeCodeForTokens(
        code: String,
        redirectUri: String,
        codeVerifier: String?,
    ): Result<Pair<String, String>> =
        Result.runCatching {
            val entity = api.exchangeCodeForTokens(code, redirectUri, codeVerifier)
            Pair(entity.accessToken, entity.refreshToken)
        }

    override suspend fun refreshTokens(refreshToken: String): Result<Pair<String, String>> =
        Result.runCatching {
            val entity = api.refreshTokens(refreshToken)
            Pair(entity.accessToken, entity.refreshToken)
        }

    override fun storeTokens(accessToken: String, refreshToken: String) {
        settings.putString(SETTINGS_KEY_ACCESS_TOKEN, accessToken)
        settings.putString(SETTINGS_KEY_REFRESH_TOKEN, refreshToken)
    }

    override fun getAccessToken(): String? =
        settings.getStringOrNull(SETTINGS_KEY_ACCESS_TOKEN)?.takeIf { it.isNotBlank() }

    override fun getRefreshToken(): String? =
        settings.getStringOrNull(SETTINGS_KEY_REFRESH_TOKEN)?.takeIf { it.isNotBlank() }

    override fun clearTokens() {
        settings.remove(SETTINGS_KEY_ACCESS_TOKEN)
        settings.remove(SETTINGS_KEY_REFRESH_TOKEN)
    }

    override suspend fun logout() {
        getRefreshToken()?.let { refresh ->
            runCatching { api.endSession(refresh) }
        }
        clearTokens()
    }

    override suspend fun getPlin(): Result<Int?> =
        Result.runCatching {
            val token = getAccessToken() ?: return@runCatching null
            api.getProfile(token).plin
        }
}