package com.coding.va.selfhelp.data.network

import com.coding.va.selfhelp.BuildKonfig
import com.coding.va.selfhelp.data.di.SHEETS_CLIENT
import com.coding.va.selfhelp.data.models.BackendApiJson
import com.coding.va.selfhelp.data.models.ConfigResponse
import com.coding.va.selfhelp.data.models.CreateEntryResponse
import com.coding.va.selfhelp.data.models.EntryData
import com.coding.va.selfhelp.data.models.EntryPayload
import com.coding.va.selfhelp.data.models.EntryResponse
import com.coding.va.selfhelp.domain.model.EntryType
import com.coding.va.selfhelp.domain.model.SheetEntryData
import io.ktor.client.HttpClient
import io.ktor.client.request.HttpRequestBuilder
import io.ktor.client.request.get
import io.ktor.client.request.header
import io.ktor.client.request.post
import io.ktor.client.request.put
import io.ktor.client.request.setBody
import io.ktor.client.statement.HttpResponse
import io.ktor.client.statement.bodyAsText
import io.ktor.http.ContentType
import io.ktor.http.contentType
import io.ktor.http.isSuccess
import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi
import kotlin.random.Random
import kotlin.time.Clock
import kotlin.time.ExperimentalTime
import org.koin.core.annotation.Named
import org.koin.core.annotation.Single

/**
 * Talks to the self-help backend. The Google service account, the sheet id and
 * the row/column layout all live server-side; the app exchanges typed entry
 * payloads and only signs its requests with a narrow per-client secret
 * (HMAC-SHA256 with timestamp + nonce, see backend/README.md).
 */
@Single
@OptIn(ExperimentalTime::class, ExperimentalEncodingApi::class)
class BackendServiceImp(
    @Named(SHEETS_CLIENT) private val client: HttpClient,
) : BackendService {

    private val json = BackendApiJson.instance

    override suspend fun getConfig(): Result<ConfigResponse> {
        val path = "/api/v1/config"
        return Result.runCatching {
            client.get(path) {
                signRequest(method = "GET", path = path, bodyText = "")
            }.decodeOrThrow(ConfigResponse.serializer())
        }
    }

    override suspend fun createEntry(type: EntryType): Result<CreateEntryResponse> {
        val path = "/api/v1/entries/${type.name}"
        return Result.runCatching {
            client.post(path) {
                signRequest(method = "POST", path = path, bodyText = "")
            }.decodeOrThrow(CreateEntryResponse.serializer())
        }
    }

    override suspend fun writeEntry(
        entry: SheetEntryData,
        payload: EntryPayload,
    ): Result<EntryResponse> {
        val path = "/api/v1/entries/${entry.type.name}/${entry.rowNumber}"
        val bodyText = json.encodeToString(EntryPayload.serializer(), payload)
        return Result.runCatching {
            client.put(path) {
                contentType(ContentType.Application.Json)
                setBody(bodyText)
                signRequest(method = "PUT", path = path, bodyText = bodyText)
            }.decodeOrThrow(EntryResponse.serializer())
        }
    }

    override suspend fun markPrinted(entry: SheetEntryData): Result<Unit> {
        val path = "/api/v1/entries/${entry.type.name}/${entry.rowNumber}/printed"
        return Result.runCatching {
            val response = client.put(path) {
                signRequest(method = "PUT", path = path, bodyText = "")
            }
            if (!response.status.isSuccess()) response.fail()
        }
    }

    override suspend fun getEntry(
        entry: EntryData
    ): Result<EntryResponse> {
        val path = "/api/v1/entries/${entry.type.name}/${entry.rowNumber}"
        return Result.runCatching {
            client.get(path) {
                signRequest(method = "GET", path = path, bodyText = "")
            }.decodeOrThrow(EntryResponse.serializer())
        }
    }

    /**
     * Adds the backend auth headers:
     *   canonical = METHOD \n PATH \n TIMESTAMP \n NONCE \n SHA256_HEX(BODY)
     *   X-Signature = Base64( HMAC-SHA256( clientSecret, canonical ) )
     */
    private fun HttpRequestBuilder.signRequest(
        method: String,
        path: String,
        bodyText: String,
    ) {
        val timestamp = Clock.System.now().epochSeconds.toString()
        val nonce = Sha256.hex(Random.nextBytes(16))
        val canonical = listOf(
            method.uppercase(),
            path,
            timestamp,
            nonce,
            Sha256.hex(Sha256.digest(bodyText.encodeToByteArray())),
        ).joinToString("\n")
        val signature = Base64.encode(
            HmacSha256.sign(BuildKonfig.BACKEND_CLIENT_SECRET.encodeToByteArray(), canonical.encodeToByteArray())
        )
        header("X-Client-Id", BuildKonfig.BACKEND_CLIENT_ID)
        header("X-Timestamp", timestamp)
        header("X-Nonce", nonce)
        header("X-Signature", signature)
    }

    private suspend fun <T> HttpResponse.decodeOrThrow(deserializer: kotlinx.serialization.DeserializationStrategy<T>): T {
        if (!status.isSuccess()) fail()
        return json.decodeFromString(deserializer, bodyAsText())
    }

    private suspend fun HttpResponse.fail(): Nothing {
        // Read the body once and carry the server's message into the exception,
        // so callers can surface a useful reason instead of just a status code.
        val body = runCatching { bodyAsText() }.getOrDefault("")
        println("Backend API error ${status.value}: $body")
        val detail = extractError(body)
        throw Exception("Backend request failed (${status.value})${if (detail.isNotBlank()) ": $detail" else ""}")
    }

    /** Pulls the `error` field out of the backend's `{ "error": "…" }` body, else the raw text. */
    private fun extractError(body: String): String = runCatching {
        (json.parseToJsonElement(body) as? kotlinx.serialization.json.JsonObject)
            ?.get("error")?.let { (it as? kotlinx.serialization.json.JsonPrimitive)?.content }
            ?: body
    }.getOrDefault(body).trim().take(160)
}
