package com.coding.va.selfhelp.presentation.screens.recharge.model

sealed class RechargeEvent {

    data class UpdateRechargeForm(val form: RechargeForm) : RechargeEvent()

    data class AddPowerSupplier(val resource: Int) : RechargeEvent()

    data class RemovePowerSupplier(val resource: Int, val row: Int) : RechargeEvent()

    data object DismissError : RechargeEvent()

    data object AddRecharge : RechargeEvent()

    data object Verify : RechargeEvent()

    data object Back : RechargeEvent()
}