package com.coding.va.selfhelp.presentation.screens.login.model

sealed class LoginScreenDisplay {
    data object Loading : LoginScreenDisplay()

    data class Display(
        val title: String,
        val statusLabel: String,
        val isAuthenticating: Boolean,
        val backButton: String,
    ) : LoginScreenDisplay()

    data class Error(
        val title: String,
        val description: String,
        val retryButton: String,
        val backButton: String,
    ) : LoginScreenDisplay()

    data class LoggedIn(
        val title: String,
        val label: String,
        val backButton: String,
    ) : LoginScreenDisplay()
}

sealed class LoginScreenEvent {
    data object RetrySignIn : LoginScreenEvent()
    data object Back : LoginScreenEvent()
}