package com.coding.va.selfhelp.presentation.screens.character.detail

private const val BASE = "https://the-vortex.nl/wp-content/uploads"

private val loresheetMap: List<Pair<String, String>> = listOf(
    // Alchemy
    "herb lore" to "$BASE/2024/06/Kennis_van_kruiden.pdf",
    "brew healing" to "$BASE/2024/06/Genezende_Dranken.pdf",
    "brew herbal" to "$BASE/2024/06/Kruiden_Elixers.pdf",
    "brew magic" to "$BASE/2024/06/Magische_Elixers.pdf",
    "brew hallucinogen" to "$BASE/2024/06/Hallucinerende_Elixers.pdf",
    "brew poison" to "$BASE/2024/06/Giffen.pdf",

    // Crafting
    "mastersmith" to "$BASE/2026/03/Crafting_loresheets.pdf",
    "carpenter" to "$BASE/2026/03/Crafting_loresheets.pdf",
    "tailor" to "$BASE/2026/03/Crafting_loresheets.pdf",
    "bookbinder" to "$BASE/2026/03/Crafting_loresheets.pdf",
    "leatherworker" to "$BASE/2026/03/Crafting_loresheets.pdf",
    "jeweler" to "$BASE/2026/03/Crafting_loresheets.pdf",
    "gemsetter" to "$BASE/2026/03/Crafting_loresheets.pdf",

    // Glyph & Rune mastery → Imbue loresheet
    "glyph mastery" to "$BASE/2024/06/Imbue_loresheet.pdf",
    "rune mastery" to "$BASE/2024/06/Imbue_loresheet.pdf",

    // Glyph & Rune use → their own loresheets
    "glyph" to "$BASE/2022/03/Mage-Glyphs.pdf",
    "rune" to "$BASE/2022/03/Priest-Runes.pdf",
)

fun getLoresheetUrl(skillName: String): String? {
    val lower = skillName.lowercase().trim()
    return loresheetMap.firstOrNull { (prefix, _) -> lower.startsWith(prefix) }?.second
}
