@Composable
fun MandateSubmittedScreen(
    formTypeLabel: String,
    subject: String,
    cardCode: String,
    mainActions: MainActions,
) {
    val strings = LocalStrings.current.mandate

    Column(Modifier.fillMaxSize().background(paper)) {
        VortexTopBar()
        KioskScrollColumn(
            modifier = Modifier
                .weight(1f)
                .fillMaxWidth(),
            contentPadding = PaddingValues(horizontal = 24.dp, vertical = 32.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
        ) {
            Column(Modifier.widthIn(max = 460.dp).fillMaxWidth(), horizontalAlignment = Alignment.CenterHorizontally) {
                Box(
                    modifier = Modifier
                        .size(96.dp)
                        .clip(CircleShape)
                        .background(Brush.radialGradient(colors = listOf(Color(0xFFB52020), crest), center = Offset(0.35f * 96f, 0.30f * 96f)))
                        .border(3.dp, giltLight, CircleShape),
                    contentAlignment = Alignment.Center,
                ) {
                    Text(text = "✓", color = pureWhite, fontSize = 44.sp)
                }

                Text(
                    text = strings.submittedTitle,
                    style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.Bold, fontSize = 32.sp),
                    color = ink,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.padding(top = 24.dp).semantics { heading() },
                )
                Text(
                    text = strings.submittedDescription,
                    style = TextStyle(fontFamily = BodyFamily(), fontSize = 17.sp, lineHeight = 27.sp),
                    color = ink2,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.padding(top = 8.dp),
                )
                Text(
                    text = "$formTypeLabel — $subject",
                    style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.SemiBold, fontSize = 18.sp),
                    color = ink,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.padding(top = 16.dp),
                )

                Column(
                    modifier = Modifier
                        .padding(top = 24.dp)
                        .fillMaxWidth()
                        .clip(RoundedCornerShape(5.dp))
                        .background(paperSunken)
                        .border(1.dp, vellumLine, RoundedCornerShape(5.dp))
                        .padding(24.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                ) {
                    Text(text = strings.submittedCodeLabel, style = TextStyle(fontFamily = BodyFamily(), fontSize = 13.sp), color = ink3)
                    Text(
                        text = cardCode,
                        style = vortexMono().copy(fontSize = 30.sp, fontWeight = FontWeight.SemiBold, letterSpacing = 3.sp),
                        color = crimson,
                        modifier = Modifier.padding(top = 6.dp),
                    )
                }

                VortexButton(
                    text = strings.submittedDoneButton,
                    onClick = { mainActions.home() },
                    modifier = Modifier.padding(top = 24.dp).fillMaxWidth(),
                )
                Spacer(Modifier.height(24.dp))
            }
        }
    }
}
