package com.coding.va.selfhelp.domain.use_cases

import com.coding.va.selfhelp.domain.constants.Constants
import com.coding.va.selfhelp.domain.model.SavedCreation
import com.coding.va.selfhelp.domain.model.SavedCreations
import com.russhwolf.settings.Settings
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import org.koin.core.component.KoinComponent
import org.koin.core.annotation.Factory


@Factory
class SavedCreationUseCase() : KoinComponent {

    val settings = Settings()

    fun getSavedCreations(): Result<SavedCreations> {
        return Result.runCatching {
            Json.decodeFromString<SavedCreations>(settings.getString(Constants.SAVED_CREATIONS, ""))
        }
    }

    fun set(item: SavedCreation): Result<Unit> {
        return Result.runCatching {
            val savedCreations = getSavedCreations().getOrElse { SavedCreations(emptyList<SavedCreation>()) }
            val newList = savedCreations.items.toMutableList()
            newList.add(item)
            settings.putString(Constants.SAVED_CREATIONS, Json.encodeToString(SavedCreations(newList)))
        }
    }
}