package com.coding.va.selfhelp.presentation.screens.mundane

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.coding.va.selfhelp.domain.use_cases.AddMundaneItem
import com.coding.va.selfhelp.domain.use_cases.CanMakeCreation
import com.coding.va.selfhelp.domain.use_cases.GetActiveCharacterUseCase
import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.presentation.methods.ApiErrorDisplayProvider
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.presentation.screens.mainscreen.destinations.MainDestinations
import com.coding.va.selfhelp.presentation.screens.mundane.model.MundaneEvent
import com.coding.va.selfhelp.presentation.screens.mundane.model.MundaneInspirationSupplier
import com.coding.va.selfhelp.presentation.screens.mundane.model.isValid
import com.coding.va.selfhelp.presentation.screens.mundane.model.meetsMinRequirements
import com.coding.va.selfhelp.presentation.screens.mundane.model.toResourcesText
import com.coding.va.selfhelp.presentation.screens.mundane.model.toVortexCard
import com.coding.va.selfhelp.presentation.screens.mundane.model.toVerifySheet
import com.coding.va.selfhelp.presentation.screens.success.model.SuccessData
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import org.koin.android.annotation.KoinViewModel

@KoinViewModel
class MundaneViewModel(
    private val addMundaneItem: AddMundaneItem,
    private val canMakeCreation: CanMakeCreation,
    private val getActiveCharacter: GetActiveCharacterUseCase,
    private val strings: AppStrings,
) : ViewModel() {

    private val _display = MutableStateFlow(MundaneDisplayProvider.provide(strings))
    val display = _display.asStateFlow()

    private var mainActions: MainActions? = null

    fun initVM(actions: MainActions) {
        mainActions = actions
        prefillActiveCharacter()
    }

    private fun prefillActiveCharacter() {
        val active = getActiveCharacter() ?: return
        val plin = Pair(active.plin.toString(), active.chin.toString())
        val currentForm = _display.value.form
        if (currentForm.crafterPlin.first.isNotBlank()) return
        _display.value = _display.value.copy(
            form = currentForm.copy(
                crafterPlin = plin,
                inspirationSuppliers = currentForm.inspirationSuppliers.mapValues { (_, supplier) ->
                    if (supplier.plin.first.isBlank()) supplier.copy(plin = plin) else supplier
                }
            )
        )
    }

    fun onEvent(event: MundaneEvent) {
        viewModelScope.launch {
            when (event) {
                is MundaneEvent.UpdateForm -> {
                    _display.emit(_display.value.copy(form = event.form))
                }

                is MundaneEvent.AddInspirationSupplier -> {
                    val currentSuppliers = _display.value.form.inspirationSuppliers
                    val newKey = (currentSuppliers.keys.maxOrNull() ?: 0) + 1
                    _display.emit(
                        _display.value.copy(
                            form = _display.value.form.copy(
                                inspirationSuppliers = currentSuppliers.toMutableMap().apply {
                                    this[newKey] = MundaneInspirationSupplier()
                                }
                            )
                        )
                    )
                }

                is MundaneEvent.RemoveInspirationSupplier -> {
                    _display.emit(
                        _display.value.copy(
                            form = _display.value.form.copy(
                                inspirationSuppliers = _display.value.form.inspirationSuppliers
                                    .toMutableMap()
                                    .apply { remove(event.key) }
                            )
                        )
                    )
                }

                is MundaneEvent.Verify -> {
                    when {
                        _display.value.form.isValid() -> {
                            _display.emit(
                                _display.value.copy(
                                    shouldValidate = false,
                                    verifySheet = _display.value.form.toVerifySheet(
                                        hasErrors = false,
                                        isEnabled = canMakeCreation().getOrNull() ?: false,
                                        strings = strings,
                                    )
                                )
                            )
                        }

                        _display.value.form.meetsMinRequirements() -> {
                            _display.emit(
                                _display.value.copy(
                                    shouldValidate = true,
                                    verifySheet = _display.value.form.toVerifySheet(
                                        hasErrors = true,
                                        isEnabled = canMakeCreation().getOrNull() ?: false,
                                        strings = strings,
                                    )
                                )
                            )
                        }

                        else -> {
                            _display.emit(
                                _display.value.copy(
                                    shouldValidate = true,
                                    errorBox = MundaneDisplayProvider.requiredError(strings),
                                )
                            )
                        }
                    }
                }

                is MundaneEvent.Confirm -> {
                    submitItem()
                }

                is MundaneEvent.DismissError -> {
                    _display.emit(
                        _display.value.copy(
                            shouldValidate = true,
                            errorBox = null,
                            verifySheet = null,
                        )
                    )
                }

                is MundaneEvent.Back -> {
                    mainActions?.home()
                }
            }
        }
    }

    private fun submitItem() {
        viewModelScope.launch {
            _display.emit(
                _display.value.copy(
                    verifySheet = _display.value.verifySheet?.copy(
                        confirm = _display.value.verifySheet!!.confirm.copy(loading = true)
                    )
                )
            )
            addMundaneItem(_display.value.form)
                .onSuccess { entry ->
                    mainActions?.navigate(
                        MainDestinations.Success(
                            data = SuccessData(
                                cardDisplay = _display.value.form.toVortexCard(entry.itemId),
                                entryData = entry,
                                shouldPrintCard = true,
                                resourcesText = _display.value.form.toResourcesText(),
                                notes = _display.value.form.notes,
                            )
                        )
                    )
                }
                .onFailure {
                    _display.emit(
                        _display.value.copy(
                            shouldValidate = false,
                            verifySheet = null,
                            errorBox = ApiErrorDisplayProvider.error(it.message, strings),
                        )
                    )
                }
        }
    }
}
