package com.coding.va.selfhelp.domain.use_cases

import com.coding.va.selfhelp.domain.model.CharacterSummary
import com.coding.va.selfhelp.domain.respository.CharactersRepository
import org.koin.core.annotation.Factory

@Factory
class GetCharactersUseCase(private val repository: CharactersRepository) {
    suspend operator fun invoke(plin: Int): Result<List<CharacterSummary>> =
        repository.getCharacters(plin)
}
