@Composable
fun HistoryContent(
    display: Display,
    onEvent: ((HistoryEvent) -> Unit)? = null,
) {
    Column(
        modifier = Modifier.fillMaxWidth().padding(horizontal = 24.dp, vertical = 24.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Column(Modifier.widthIn(max = 860.dp).fillMaxWidth()) {
            Text(
                text = display.title,
                style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.Bold, fontSize = 32.sp),
                color = ink,
                modifier = Modifier.semantics { heading() },
            )
            Text(
                text = display.subtitle,
                style = TextStyle(fontFamily = BodyFamily(), fontSize = 17.sp),
                color = ink2,
                modifier = Modifier.padding(top = 6.dp),
            )
            Spacer(Modifier.height(20.dp))

            if (display.items.isEmpty()) {
                Text(
                    text = display.emptyMessage,
                    style = TextStyle(fontFamily = BodyFamily(), fontSize = 16.sp),
                    color = ink2,
                    modifier = Modifier.semantics { liveRegion = LiveRegionMode.Polite },
                )
            } else {
                Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                    display.items.forEachIndexed { index, item ->
                        HistoryCard(item, index, onClick = { onEvent?.invoke(HistoryEvent.ToggleExpand(index)) }, onEvent = onEvent)
                    }
                }
            }
        }
    }
}

@Composable
private fun HistoryCard(
    item: HistoryItemDisplay,
    index: Int,
    onClick: () -> Unit,
    onEvent: ((HistoryEvent) -> Unit)?,
) {
    val a11y = LocalStrings.current.a11y
    val codeStyle = vortexMono().copy(fontSize = 13.sp, color = crimson)

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(10.dp))
            .background(paperRaised)
            .border(1.dp, vellumLine, RoundedCornerShape(10.dp))
            .semantics {
                role = Role.Button
                stateDescription = if (item.isExpanded) a11y.expanded else a11y.collapsed
            }
            .clickable(onClick = onClick)
            .padding(horizontal = 20.dp, vertical = 16.dp),
    ) {
        Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
            Column(Modifier.weight(1f)) {
                // pill
                Box(
                    Modifier.clip(RoundedCornerShape(999.dp)).background(giltWash).padding(horizontal = 9.dp, vertical = 3.dp),
                ) {
                    Text(text = item.kindOfCreation, style = vortexMono().copy(fontSize = 11.sp), color = Color_6b551d)
                }
                item.name?.let {
                    Text(
                        text = it,
                        style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.SemiBold, fontSize = 18.sp),
                        color = ink,
                        modifier = Modifier.padding(top = 8.dp),
                    )
                }
                item.plinText?.let {
                    Text(text = it, style = TextStyle(fontFamily = BodyFamily(), fontSize = 14.sp), color = ink3, modifier = Modifier.padding(top = 2.dp))
                }
                if (item.printable) {
                    Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.padding(top = 2.dp)) {
                        Text(text = item.printerCodeLabel + " ", style = TextStyle(fontFamily = BodyFamily(), fontSize = 14.sp), color = ink3)
                        Text(text = item.cardCode, style = codeStyle)
                    }
                }
            }
            Text(text = if (item.isExpanded) "▲" else "▼", color = crimson, fontSize = 18.sp)
        }

        AnimatedVisibility(visible = item.isExpanded, enter = expandVertically(), exit = shrinkVertically()) {
            Column(Modifier.fillMaxWidth().padding(top = 12.dp)) {
                if (item.resourcesText != null) {
                    CreationSummaryDetail(
                        resources = item.resourcesText,
                        notes = item.notes ?: "",
                        modifier = Modifier.fillMaxWidth().clip(RoundedCornerShape(5.dp)).background(paperSunken).padding(12.dp),
                    )
                    Spacer(Modifier.height(8.dp))
                    item.envelopeInstruction?.let {
                        Text(text = it, style = TextStyle(fontFamily = BodyFamily(), fontSize = 14.sp), color = ink2)
                    }
                    Spacer(Modifier.height(12.dp))
                }
                if (item.canRepeat) {
                    VortexButton(
                        text = item.repeatButtonLabel,
                        onClick = { onEvent?.invoke(HistoryEvent.RepeatCreation(index)) },
                        variant = VortexButtonVariant.Secondary,
                        modifier = Modifier.fillMaxWidth(),
                    )
                    Spacer(Modifier.height(8.dp))
                }
                if (item.vortexCard != null) {
                    Column(Modifier.fillMaxWidth().clip(RoundedCornerShape(5.dp)).background(paperSunken).padding(8.dp)) {
                        VortexItemCardUIFront(display = item.vortexCard, modifier = Modifier.fillMaxWidth())
                        Spacer(Modifier.height(8.dp))
                        VortexItemCardUIBack(display = item.vortexCard, modifier = Modifier.fillMaxWidth())
                    }
                } else if (item.resourcesText == null) {
                    Text(
                        text = item.noCardDetailsText,
                        style = TextStyle(fontFamily = BodyFamily(), fontSize = 14.sp),
                        color = ink3,
                        modifier = Modifier.padding(top = 8.dp),
                    )
                }
            }
        }
    }
}

private val Color_6b551d = androidx.compose.ui.graphics.Color(0xFF6B551D)
