@Composable
fun MundaneContent(
    display: MundaneDisplay,
    onEvent: ((MundaneEvent) -> Unit)? = null,
) {
    val numberRegex = remember { Regex("^\\d+$") }
    val strings = LocalStrings.current
    val numericKeyboard = KeyboardOptions(keyboardType = KeyboardType.Number)
    val helpStyle = TextStyle(fontFamily = BodyFamily(), fontSize = 14.sp, color = ink3)

    fun update(form: com.coding.va.selfhelp.domain.model.MundaneForm) =
        onEvent?.invoke(MundaneEvent.UpdateForm(form))

    display.errorBox?.let {
        ErrorBox(display = it, onConfirmation = { onEvent?.invoke(MundaneEvent.Confirm) }, onDismissRequest = { onEvent?.invoke(MundaneEvent.DismissError) })
    }
    display.verifySheet?.let {
        VerifySheet(display = it, onConfirm = { onEvent?.invoke(MundaneEvent.Confirm) }, onDismiss = { onEvent?.invoke(MundaneEvent.DismissError) })
    }

    FormShell(
        title = display.title,
        desc = display.description,
        onBack = { onEvent?.invoke(MundaneEvent.Back) },
        cancelLabel = display.backButton,
        nextLabel = display.nextButton,
        onCancel = { onEvent?.invoke(MundaneEvent.Back) },
        onNext = { onEvent?.invoke(MundaneEvent.Verify) },
    ) {
        // ---- Skill ----
        FormSection {
            SelectableField(
                label = display.skillField.label,
                display = display.skillField,
                value = display.form.selectedSkill?.localizedName(strings),
                isError = display.shouldValidate && !display.form.isSkillSelected(),
                onSelected = { content ->
                    update(display.form.copy(selectedSkill = MundaneSkill.entries.firstOrNull { it.name == content.id }))
                },
            )
            display.form.selectedSkill?.let { skill ->
                Ledger {
                    LedgerLine(label = display.skillRequiredLabel, amount = skill.localizedRequiredSkill(strings))
                    LedgerLine(label = display.skillResourcesLabel, amount = skill.resources)
                    Text(
                        text = display.skillEffectLabel + " " + skill.localizedEffect(strings),
                        style = TextStyle(fontFamily = BodyFamily(), fontSize = 14.sp, color = ink2),
                        modifier = Modifier.padding(top = 8.dp),
                    )
                }
            }
        }

        // ---- Details ----
        FormSection {
            val hasQty = display.form.selectedSkill?.hasQuantity == true
            Row(horizontalArrangement = Arrangement.spacedBy(16.dp), verticalAlignment = Alignment.Top) {
                if (hasQty) {
                    val qtyInvalid = display.shouldValidate && !display.form.isQuantityValid()
                    VortexField(
                        fieldWidth = 150.dp, expandHelper = false,
                        label = display.quantityField.label,
                        value = display.form.quantity,
                        hint = display.quantityField.hint,
                        error = if (qtyInvalid) strings.a11y.errorNumbersOnly else null,
                        mono = true,
                        keyboardOptions = numericKeyboard,
                                numericOnly = true,
                                placeholder = "0",
                        onValueChange = { if (it.isEmpty() || it.matches(numberRegex)) update(display.form.copy(quantity = it)) },
                    )
                }
                PlinTextField(
                    display = display.crafterPlinField,
                            expandHelper = false,
                    value = display.form.crafterPlin,
                    isError = display.shouldValidate && !display.form.isCrafterPlinValid(),
                    errorText = if (display.shouldValidate && !display.form.isCrafterPlinValid()) strings.a11y.errorInvalidPlin else null,
                    onValueChange = { update(display.form.copy(crafterPlin = it)) },
                )
            }
            if (display.form.selectedSkill?.requiresTargetPlin == true) {
                Spacer(Modifier.height(16.dp))
                PlinTextField(
                    display = display.targetPlinField,
                    value = display.form.targetPlin,
                    isError = display.shouldValidate && !display.form.isTargetPlinValid(),
                    onValueChange = { update(display.form.copy(targetPlin = it)) },
                )
            }
            if (display.form.selectedSkill?.requiresSecondPlin == true) {
                Spacer(Modifier.height(16.dp))
                PlinTextField(
                    display = display.targetPlin2Field,
                    value = display.form.targetPlin2,
                    isError = display.shouldValidate && !display.form.isTargetPlin2Valid(),
                    onValueChange = { update(display.form.copy(targetPlin2 = it)) },
                )
            }
            if (display.form.selectedSkill?.requiresSkillName == true) {
                Spacer(Modifier.height(16.dp))
                val skillNameInvalid = display.shouldValidate && !display.form.isSkillNameValid()
                VortexField(
                    label = display.skillNameField.label,
                    value = display.form.skillName,
                    hint = display.skillNameField.hint,
                    error = if (skillNameInvalid) strings.mundane.skillNameError else null,
                    onValueChange = { update(display.form.copy(skillName = it)) },
                )
            }
        }

        // ---- Special Notes ----
        FormSection(title = display.notesField.label) {
            VortexField(
                value = display.form.notes,
                hint = display.notesField.hint,
                singleLine = false,
                minHeight = 96.dp,
                onValueChange = { update(display.form.copy(notes = it)) },
            )
        }

        // ---- Inspiration suppliers ----
        FormSection(title = display.inspirationSectionTitle, help = display.inspirationSupplierDescription) {
            if (display.form.hasAnyInspirationSupplied()) {
                val supplied = display.form.totalInspirationSupplied()
                val required = display.form.requiredInspirationTotal()
                val totalOk = display.form.isInspirationTotalValid()
                val glyph = if (totalOk) "✓ " else "✗ "
                Text(
                    modifier = Modifier.padding(bottom = 12.dp).semantics { liveRegion = LiveRegionMode.Polite },
                    text = glyph + display.inspirationCountLabel + "$supplied / $required",
                    style = TextStyle(fontFamily = BodyFamily(), fontSize = 15.sp, fontWeight = FontWeight.SemiBold),
                    color = if (totalOk) successInk else errorInk,
                )
            }
            Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                SupplierHeader(plinLabel = strings.common.supplierPlinLabel, amountLabel = strings.common.amountLabel)
                display.form.inspirationSuppliers.forEach { (key, supplier) ->
                    val rowInvalid = display.shouldValidate && supplier.isFilled() && !supplier.isValid()
                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalAlignment = Alignment.Top) {
                        PlinTextField(
                            display = display.inspirationSupplierPlinField,
                            expandHelper = false,
                            value = supplier.plin,
                            isError = rowInvalid,
                            errorText = if (rowInvalid) strings.a11y.errorInvalidPlin else null,
                            onValueChange = {
                                update(
                                    display.form.copy(
                                        inspirationSuppliers = display.form.inspirationSuppliers.toMutableMap().apply { this[key] = supplier.copy(plin = it) }
                                    )
                                )
                            },
                        )
                        VortexField(
                            fieldWidth = 90.dp, expandHelper = false,
                            value = supplier.amount,
                            error = if (rowInvalid) strings.a11y.errorNumbersOnly else null,
                            mono = true,
                            keyboardOptions = numericKeyboard,
                                numericOnly = true,
                                placeholder = "0",
                            onValueChange = {
                                if (it.isEmpty() || it.matches(numberRegex)) {
                                    update(
                                        display.form.copy(
                                            inspirationSuppliers = display.form.inspirationSuppliers.toMutableMap().apply { this[key] = supplier.copy(amount = it) }
                                        )
                                    )
                                }
                            },
                        )
                        if (display.form.inspirationSuppliers.size > 1) {
                            VortexIconButton(
                                symbol = "−",
                                contentDescription = strings.a11y.removeRow,
                                onClick = { onEvent?.invoke(MundaneEvent.RemoveInspirationSupplier(key)) },
                            )
                        }
                    }
                }
                VortexButton(
                    text = "＋ " + strings.common.addSupplierLabel,
                    onClick = {
                        val lastKey = display.form.inspirationSuppliers.keys.maxOrNull() ?: 1
                        onEvent?.invoke(MundaneEvent.AddInspirationSupplier(lastKey))
                    },
                    variant = VortexButtonVariant.Secondary,
                )
            }
        }

        Spacer(Modifier.height(8.dp))
    }
}
