package com.coding.va.selfhelp.auth

import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.asSharedFlow

data class OAuthCallbackData(val code: String, val state: String)

/**
 * Singleton bus that bridges platform OAuth callbacks (deep links on Android,
 * ASWebAuthenticationSession on iOS) back to the ViewModel.
 */
object OAuthBridge {
    private val _callbacks = MutableSharedFlow<OAuthCallbackData>(extraBufferCapacity = 1)
    val callbacks = _callbacks.asSharedFlow()

    private val _cancellations = MutableSharedFlow<Unit>(extraBufferCapacity = 1)
    val cancellations = _cancellations.asSharedFlow()

    suspend fun onCallback(code: String, state: String) {
        _callbacks.emit(OAuthCallbackData(code, state))
    }

    fun onCancelled() {
        _cancellations.tryEmit(Unit)
    }
}

/** Scheme used as the redirect URI for OAuth callbacks.
 *  Note: RFC 3986 forbids underscores in URI scheme names, so we use "va-selfhelp" (hyphen instead).
 */
const val OAUTH_CALLBACK_SCHEME = "va-selfhelp"

/** Full callback URI sent to the OAuth provider. */
const val OAUTH_CALLBACK_URI = "$OAUTH_CALLBACK_SCHEME://oauth/callback"