package com.coding.va.selfhelp.presentation.screens.mandate.submitted.navigation

import androidx.navigation.NavGraphBuilder
import androidx.navigation.compose.composable
import androidx.navigation.toRoute
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.presentation.screens.mainscreen.destinations.MainDestinations
import com.coding.va.selfhelp.presentation.screens.mandate.submitted.MandateSubmittedScreen

fun NavGraphBuilder.MandateSubmittedRoute(actions: MainActions) {
    composable<MainDestinations.MandateSubmitted> { backStackEntry ->
        val args = backStackEntry.toRoute<MainDestinations.MandateSubmitted>()
        MandateSubmittedScreen(
            formTypeLabel = args.formTypeLabel,
            subject = args.subject,
            cardCode = args.cardCode,
            mainActions = actions,
        )
    }
}
