package com.coding.va.selfhelp.theme

import androidx.compose.ui.unit.dp

/**
 * Non-color design tokens (radius, borders, spacing, elevation) from the handoff `ds.css :root`.
 * Kept as plain objects so call sites read `VortexRadius.md`, `VortexSpacing.x4`, etc.
 */

object VortexRadius {
    val sm = 3.dp
    val md = 5.dp   // controls (refines the old 4dp)
    val lg = 10.dp  // cards
    val seal = 999.dp
}

object VortexBorder {
    val hairlineWidth = 1.dp
    val hairlineColor = vellumLine     // 1px vellum-line
    val controlWidth = 1.5.dp
    val controlColor = inkFaint        // 1.5px ink-faint
}

/** 4-based spacing scale. */
object VortexSpacing {
    val x1 = 4.dp
    val x2 = 8.dp
    val x3 = 12.dp
    val x4 = 16.dp
    val x5 = 20.dp
    val x6 = 24.dp
    val x8 = 32.dp
    val x10 = 40.dp
    val x12 = 48.dp
}

/**
 * Warm elevation. Compose `elevation` alone renders neutral gray; pass [warmSpot] / [warmAmbient]
 * to `Modifier.shadow(..., spotColor = , ambientColor = )` to get the parchment-warm shadow.
 */
object VortexElevation {
    val sm = 1.dp
    val md = 3.dp
    val lg = 8.dp
    val warmSpot = ink.copy(alpha = 0.18f)
    val warmAmbient = ink.copy(alpha = 0.12f)
}
