@Composable
fun SuccessContent(
    display: SuccessDisplay.Data,
    onEvent: ((SuccessEvent) -> Unit)? = null,
    isLoading: Boolean = false,
) {
    val coroutineScope = rememberCoroutineScope()
    val didPrintCard = remember { mutableStateOf(false) }

    display.vortexPrintingCard?.let {
        val card: @Composable () -> Unit = remember { @Composable { VortexItemCard(it, isPrinting = true) } }
        coroutineScope.launch {
            if (getPlatform() == TYPE.DESKTOP) {
                delay(100)
                val shot = captureComposable(card)
                delay(100)
                if (!didPrintCard.value) {
                    didPrintCard.value = true
                    onEvent?.invoke(SuccessEvent.PrintCard(shot))
                }
            }
        }
    }

    Column(Modifier.fillMaxSize().background(paper)) {
        VortexTopBar()
        KioskScrollColumn(
            modifier = Modifier
                .fillMaxWidth()
                .semantics { liveRegion = LiveRegionMode.Assertive },
            contentPadding = PaddingValues(horizontal = 24.dp, vertical = 32.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
        ) {
            Column(
                modifier = Modifier.widthIn(max = 460.dp).fillMaxWidth(),
                horizontalAlignment = Alignment.CenterHorizontally,
            ) {
                // seal
                Box(
                    modifier = Modifier
                        .size(96.dp)
                        .clip(CircleShape)
                        .background(Brush.radialGradient(colors = listOf(Color(0xFFB52020), crest), center = Offset(0.35f * 96f, 0.30f * 96f)))
                        .border(3.dp, giltLight, CircleShape)
                        .placeholder(isLoading),
                    contentAlignment = Alignment.Center,
                ) {
                    Text(text = "✓", color = pureWhite, fontSize = 44.sp)
                }

                Text(
                    text = display.title,
                    style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.Bold, fontSize = 32.sp),
                    color = ink,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.padding(top = 24.dp).placeholder(isLoading).semantics { heading() },
                )
                Text(
                    text = display.description,
                    style = TextStyle(fontFamily = BodyFamily(), fontSize = 17.sp, lineHeight = 27.sp),
                    color = ink2,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.padding(top = 8.dp).placeholder(isLoading),
                )

                // code / extra-info well
                Column(
                    modifier = Modifier
                        .padding(top = 24.dp)
                        .fillMaxWidth()
                        .clip(RoundedCornerShape(5.dp))
                        .background(paperSunken)
                        .border(1.dp, vellumLine, RoundedCornerShape(5.dp))
                        .padding(24.dp)
                        .placeholder(isLoading),
                    horizontalAlignment = Alignment.CenterHorizontally,
                ) {
                    Text(
                        text = display.extraInfo,
                        style = TextStyle(fontFamily = BodyFamily(), fontSize = 16.sp, lineHeight = 26.sp),
                        color = ink2,
                        textAlign = TextAlign.Center,
                    )
                }

                VortexButton(
                    text = display.doneButton,
                    onClick = { onEvent?.invoke(SuccessEvent.Close) },
                    modifier = Modifier.padding(top = 24.dp).fillMaxWidth().placeholder(isLoading),
                )
                Box(Modifier.padding(bottom = 24.dp))
            }
        }
    }
}
