package com.coding.va.selfhelp.presentation.screens.success

import androidx.compose.ui.text.AnnotatedString
import androidx.compose.ui.text.SpanStyle
import androidx.compose.ui.text.buildAnnotatedString
import androidx.compose.ui.text.font.FontFamily
import androidx.compose.ui.text.withStyle
import com.coding.va.selfhelp.di.getPlatform
import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.presentation.screens.success.model.SuccessData
import com.coding.va.selfhelp.presentation.screens.success.model.SuccessDisplay
import com.coding.va.selfhelp.theme.vortexRed

object SuccessDisplayMapper {

    fun mapSuccess(data: SuccessData?, strings: AppStrings) = SuccessDisplay.Data(
        title = strings.success.title,
        description = buildAnnotatedString {
            append(strings.success.descriptionPrefix)
            withStyle(style = SpanStyle(color = vortexRed, fontFamily = FontFamily.Serif)) {
                append("${data?.entryData?.itemId}")
            }
            append(strings.success.descriptionSuffix)
        },
        vortexPrintingCard = if (data?.shouldPrintCard == true) data.cardDisplay else null,
        doneButton = strings.success.doneButton,
        extraInfo = if (getPlatform().isMobile) buildAnnotatedString {
            append(strings.success.extraInfoPrefix)
            withStyle(style = SpanStyle(color = vortexRed, fontFamily = FontFamily.Serif)) {
                append("${data?.entryData?.getCardCode}")
            }
            append(strings.success.extraInfoSuffix)
        } else AnnotatedString("")
    )

    fun provideFailure(strings: AppStrings) = SuccessDisplay.Failure(
        title = strings.success.failureTitle,
        description = strings.success.failureDescription,
        retryButton = strings.success.failureRetryButton,
    )

    fun mapPrinting(data: SuccessData?, strings: AppStrings): SuccessDisplay = SuccessDisplay.Loading(
        mapSuccess(data, strings)
    )

    fun provideLoading(strings: AppStrings): SuccessDisplay = SuccessDisplay.Loading(
        mapSuccess(null, strings)
    )
}
