@Composable
fun CharacterSelectContent(
    display: CharacterSelectScreenDisplay.Display,
    onEvent: (CharacterSelectEvent) -> Unit,
) {
    Column(
        modifier = Modifier.fillMaxWidth().padding(horizontal = 24.dp, vertical = 24.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Column(Modifier.widthIn(max = 860.dp).fillMaxWidth()) {
            Text(
                text = display.title,
                style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.Bold, fontSize = 32.sp, lineHeight = 38.sp),
                color = ink,
                modifier = Modifier.semantics { heading() },
            )
            Text(
                text = display.subtitle,
                style = TextStyle(fontFamily = BodyFamily(), fontSize = 17.sp),
                color = ink2,
                modifier = Modifier.padding(top = 6.dp),
            )
            Spacer(Modifier.height(20.dp))
            Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                display.characters.forEach { character ->
                    CharacterRow(character) {
                        onEvent(CharacterSelectEvent.SelectCharacter(character.plin, character.chin))
                    }
                }
            }
        }
    }
}

@Composable
private fun CharacterRow(character: CharacterSelectItemDisplay, onSelect: () -> Unit) {
    RowCard(
        onClick = onSelect,
        trailing = { StatusBadge(character.statusLabel) },
    ) {
        Text(
            text = character.name,
            style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.SemiBold, fontSize = 18.sp),
            color = ink,
        )
        Text(
            text = "CHIN ${character.chin}",
            style = TextStyle(fontFamily = BodyFamily(), fontSize = 14.sp),
            color = ink3,
            modifier = Modifier.padding(top = 2.dp),
        )
    }
}

@Composable
private fun StatusBadge(status: String) {
    val isActive = status.lowercase() == "active"
    val bgColor = if (isActive) successInk else tertiaryTextColor
    val glyph = if (isActive) "● " else "○ "
    Box(
        modifier = Modifier
            .clip(RoundedCornerShape(999.dp))
            .background(bgColor)
            .padding(horizontal = 10.dp, vertical = 4.dp),
    ) {
        Text(text = glyph + status, color = pureWhite, fontSize = 12.sp, fontWeight = FontWeight.Medium)
    }
}